CREATE INDEX restaurant_settings_updated_by_idx ON public.restaurant_settings USING btree (updated_by);

CREATE INDEX restaurant_tables_branch_active_idx ON public.restaurant_tables USING btree (branch_id, is_active, table_number);

CREATE INDEX rider_locations_rider_recorded_idx ON public.rider_locations USING btree (rider_user_id, recorded_at DESC);

CREATE INDEX rider_profiles_branch_availability_idx ON public.rider_profiles USING btree (branch_id, availability_status, is_active);

CREATE INDEX rider_push_subscriptions_rider_active_idx ON public.rider_push_subscriptions USING btree (rider_user_id, is_active);

CREATE INDEX rider_status_history_user_changed_idx ON public.rider_status_history USING btree (rider_user_id, changed_at DESC);

CREATE INDEX staff_role_audit_branch_created_idx ON public.staff_role_audit USING btree (branch_id, created_at DESC);

CREATE INDEX staff_role_audit_target_created_idx ON public.staff_role_audit USING btree (target_user_id, created_at DESC);

CREATE INDEX subcategories_category_active_sort_idx ON public.subcategories USING btree (category_id, is_active, sort_order);

CREATE INDEX user_roles_branch_id_idx ON public.user_roles USING btree (branch_id);

CREATE INDEX user_roles_created_by_idx ON public.user_roles USING btree (created_by);

CREATE INDEX user_roles_user_branch_active_idx ON public.user_roles USING btree (user_id, branch_id, is_active);

CREATE OR REPLACE FUNCTION private.has_staff_role(p_branch_id uuid, p_roles text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = (select auth.uid())
      and ur.is_active
      and ur.role = any(p_roles)
      and (
        p_branch_id is null
        or ur.branch_id is null
        or ur.branch_id = p_branch_id
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION private.is_current_rider_for_order(p_order_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.delivery_tasks dt
    join public.delivery_assignments da on da.delivery_task_id=dt.id
    where dt.order_id=p_order_id
      and da.rider_user_id=(select auth.uid())
      and da.is_current
      and da.status in ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery')
  )
  or exists (
    select 1
    from public.delivery_tasks dt
    join public.delivery_assignments da on da.delivery_task_id=dt.id
    join public.user_roles ur
      on ur.user_id=da.rider_user_id
     and ur.role='rider'
     and ur.is_active=true
     and (ur.branch_id is null or ur.branch_id=dt.branch_id)
    join public.rider_profiles rp
      on rp.user_id=da.rider_user_id
     and rp.branch_id=dt.branch_id
     and rp.is_active=true
     and rp.availability_status<>'suspended'
    where dt.order_id=p_order_id
      and dt.status='failed'
      and dt.return_confirmed_at is null
      and da.rider_user_id=(select auth.uid())
      and da.status='failed'
  );
$function$
;

CREATE OR REPLACE FUNCTION private.is_current_rider_for_task(p_task_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1 from public.delivery_assignments da
    where da.delivery_task_id = p_task_id and da.rider_user_id = (select auth.uid())
      and da.is_current and da.status in ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery')
  );
$function$
;

CREATE OR REPLACE FUNCTION private.can_access_order(p_order_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.orders o
    where o.id = p_order_id
      and (
        private.has_staff_role(o.branch_id, array['owner','admin','manager','cashier','kitchen']::text[])
        or private.is_current_rider_for_order(o.id)
        or exists (
          select 1
          from public.delivery_tasks dt
          join public.delivery_assignments da on da.delivery_task_id = dt.id
          join public.user_roles ur
            on ur.user_id = da.rider_user_id
           and ur.role = 'rider'
           and ur.is_active = true
           and (ur.branch_id is null or ur.branch_id = dt.branch_id)
          join public.rider_profiles rp
            on rp.user_id = da.rider_user_id
           and rp.branch_id = dt.branch_id
           and rp.is_active = true
           and rp.availability_status <> 'suspended'
          where dt.order_id = o.id
            and dt.status = 'failed'
            and dt.return_confirmed_at is null
            and da.rider_user_id = (select auth.uid())
            and da.status = 'failed'
        )
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION private.can_access_delivery_task(p_task_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.delivery_tasks dt
    where dt.id = p_task_id
      and (
        private.has_staff_role(dt.branch_id, array['owner','admin','manager','cashier','kitchen']::text[])
        or private.is_current_rider_for_task(dt.id)
        or (
          dt.status = 'failed'
          and dt.return_confirmed_at is null
          and exists (
            select 1
            from public.delivery_assignments da
            join public.user_roles ur
              on ur.user_id = da.rider_user_id
             and ur.role = 'rider'
             and ur.is_active = true
             and (ur.branch_id is null or ur.branch_id = dt.branch_id)
            join public.rider_profiles rp
              on rp.user_id = da.rider_user_id
             and rp.branch_id = dt.branch_id
             and rp.is_active = true
             and rp.availability_status <> 'suspended'
            where da.delivery_task_id = dt.id
              and da.rider_user_id = (select auth.uid())
              and da.status = 'failed'
          )
        )
        or exists (
          select 1
          from public.delivery_task_offers dto
          where dto.delivery_task_id = dt.id
            and dto.rider_user_id = (select auth.uid())
            and dto.status = 'offered'
        )
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION private.create_manual_assignment_acceptance_offer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_offer_id uuid; v_offer_round integer;
BEGIN
  IF NEW.status<>'assigned' OR NEW.offer_id IS NOT NULL THEN RETURN NEW; END IF;
  SELECT coalesce(max(dto.offer_round),0)+1 INTO v_offer_round
  FROM public.delivery_task_offers dto WHERE dto.delivery_task_id=NEW.delivery_task_id;
  INSERT INTO public.delivery_task_offers(delivery_task_id,rider_user_id,offer_round,status,offered_at,expires_at)
  VALUES(NEW.delivery_task_id,NEW.rider_user_id,v_offer_round,'offered',NEW.assigned_at,NEW.assigned_at+interval '60 seconds')
  RETURNING id INTO v_offer_id;
  UPDATE public.delivery_assignments SET offer_id=v_offer_id WHERE id=NEW.id AND offer_id IS NULL;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.enqueue_delivery_offer_push()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_offer_ids uuid[];
  v_token text;
BEGIN
  SELECT coalesce(
    array_agg(no.id ORDER BY no.id) FILTER (WHERE no.status = 'offered'),
    ARRAY[]::uuid[]
  )
  INTO v_offer_ids
  FROM new_offers no;

  IF cardinality(v_offer_ids) = 0 THEN
    RETURN NULL;
  END IF;

  -- Only call the Edge Function if at least one recipient has an active
  -- push device. This avoids a webhook for realtime-only riders.
  IF NOT EXISTS (
    SELECT 1
    FROM new_offers no
    JOIN public.rider_push_subscriptions ps
      ON ps.rider_user_id = no.rider_user_id
     AND ps.is_active = true
    WHERE no.status = 'offered'
  ) THEN
    RETURN NULL;
  END IF;

  SELECT c.webhook_token
    INTO v_token
  FROM private.rider_push_config c
  WHERE c.singleton = true;

  IF v_token IS NULL THEN
    RETURN NULL;
  END IF;

  -- A multi-rider INSERT ... SELECT now sends one webhook containing all
  -- new offer ids, rather than one Edge Function invocation per rider.
  PERFORM net.http_post(
    url := 'https://nthtslzeqglcforbsirz.supabase.co/functions/v1/hfp-delivery-api',
    body := jsonb_build_object('offer_ids', to_jsonb(v_offer_ids)),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-flame-chick-push-hook', v_token
    ),
    timeout_milliseconds := 3000
  );

  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.guard_assignment_acceptance_deadline()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_trusted_reassignment boolean :=
    coalesce(pg_catalog.current_setting('flame_chick.allow_assignment_reassign',true),'off')='on';
BEGIN
  IF OLD.status='assigned'
     AND OLD.accepted_at IS NULL
     AND pg_catalog.clock_timestamp() >= OLD.assigned_at + interval '60 seconds'
     AND (
       NEW.status='accepted'
       OR (NEW.status='reassigned' AND NOT v_trusted_reassignment)
     ) THEN
    RAISE EXCEPTION USING ERRCODE='22023',
      MESSAGE='DELIVERY_ACCEPTANCE_EXPIRED: The 60-second response window has ended. Refresh the Rider app for the next assignment.';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.handle_delivery_assignment_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_now timestamptz := pg_catalog.now();
begin
  update public.delivery_task_offers
  set status = 'withdrawn',
      responded_at = coalesce(responded_at, v_now),
      response_reason = case
        when delivery_task_id = new.delivery_task_id then 'A rider was assigned to this delivery'
        else 'This rider accepted another delivery'
      end
  where status = 'offered'
    and id is distinct from new.offer_id
    and (delivery_task_id = new.delivery_task_id or rider_user_id = new.rider_user_id);
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.handle_order_status_side_effects()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_task_id uuid;
  v_actor_user_id uuid;
  v_actor_type text;
  v_from_status text;
begin
  v_from_status := case when tg_op = 'INSERT' then null else old.status end;

  if tg_op = 'INSERT' or new.status is distinct from old.status then
    v_actor_user_id := coalesce(
      new.last_status_changed_by,
      (select auth.uid()),
      new.accepted_by,
      new.rejected_by,
      new.cancelled_by_user_id,
      new.cashier_id
    );

    v_actor_type := coalesce(
      new.last_status_actor_type,
      case
        when v_actor_user_id is not null and exists (
          select 1 from public.rider_profiles rp where rp.user_id = v_actor_user_id
        ) then 'rider'
        when v_actor_user_id is not null and private.has_staff_role(new.branch_id, array['owner','admin']::text[]) then 'admin'
        when v_actor_user_id is not null then 'staff'
        when tg_op = 'INSERT' and new.status = 'new' and new.source in ('website','whatsapp','phone') then 'customer'
        else 'system'
      end
    );

    insert into public.order_status_history(
      order_id, from_status, to_status, actor_user_id, actor_type, source, reason
    )
    values (
      new.id, v_from_status, new.status, v_actor_user_id, v_actor_type,
      new.source, new.last_status_change_reason
    );

    insert into public.order_events(order_id, event_type, actor_user_id, actor_type, payload)
    values (
      new.id,
      case when tg_op = 'INSERT' then 'order.received' else 'order.status_changed' end,
      v_actor_user_id,
      v_actor_type,
      jsonb_build_object(
        'from_status', v_from_status,
        'to_status', new.status,
        'source', new.source,
        'reason', new.last_status_change_reason
      )
    );

    insert into public.event_outbox(event_type, aggregate_type, aggregate_id, payload)
    values (
      case when tg_op = 'INSERT' then 'order.received' else 'order.status_changed' end,
      'order',
      new.id,
      jsonb_build_object(
        'order_id', new.id,
        'branch_id', new.branch_id,
        'status', new.status,
        'from_status', v_from_status
      )
    );

    if new.status = 'preparing'
       and new.fulfillment_type = 'delivery'
       and not exists (select 1 from public.delivery_tasks dt where dt.order_id = new.id) then
      insert into public.delivery_tasks(
        order_id, branch_id, status, recipient_name_snapshot, recipient_phone_snapshot,
        address_snapshot, area_name_snapshot, delivery_fee_snapshot,
        delivery_instructions_snapshot, dispatch_started_at
      )
      values (
        new.id, new.branch_id, 'dispatch_pending',
        new.customer_name, new.customer_phone,
        coalesce(new.delivery_address, ''),
        new.delivery_area_name_snapshot,
        new.delivery_fee,
        new.delivery_instructions,
        now()
      )
      returning id into v_task_id;

      insert into public.event_outbox(event_type, aggregate_type, aggregate_id, payload)
      values (
        'delivery.task_created',
        'delivery_task',
        v_task_id,
        jsonb_build_object(
          'delivery_task_id', v_task_id,
          'order_id', new.id,
          'branch_id', new.branch_id
        )
      );
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.on_order_ready_start_delivery_offers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status = 'ready' and old.status is distinct from new.status
    and new.fulfillment_type = 'delivery' then
    perform private.start_ready_delivery_offers_for_branch(new.branch_id);
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.on_rider_becomes_available_start_delivery_offers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.is_active=true AND NEW.accepting_jobs=true
    AND NEW.availability_status='available'
    AND NEW.last_seen_at >= pg_catalog.now()-interval '4 minutes'
    AND (
      OLD.accepting_jobs IS DISTINCT FROM NEW.accepting_jobs
      OR OLD.availability_status IS DISTINCT FROM NEW.availability_status
      OR OLD.last_seen_at IS NULL
      OR OLD.last_seen_at < pg_catalog.now()-interval '4 minutes'
    ) THEN
    PERFORM private.start_ready_delivery_offers_for_branch(NEW.branch_id);
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.prevent_rider_double_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_branch_id uuid;
  v_profile public.rider_profiles%rowtype;
  v_now timestamptz;
begin
  select dt.branch_id into v_branch_id from public.delivery_tasks dt where dt.id = new.delivery_task_id;
  if not found then raise exception using errcode='P0002', message='DELIVERY_TASK_NOT_FOUND: Delivery task does not exist.'; end if;

  select * into v_profile
  from public.rider_profiles rp
  where rp.user_id=new.rider_user_id and rp.branch_id=v_branch_id and rp.is_active=true
  for update;
  if not found then raise exception using errcode='42501', message='RIDER_PROFILE_REQUIRED: Active rider profile is required.'; end if;

  v_now := pg_catalog.clock_timestamp();
  if v_profile.availability_status <> 'available'
    or v_profile.accepting_jobs is not true
    or v_profile.last_seen_at is null
    or v_profile.last_seen_at < v_now - interval '4 minutes' then
    raise exception using errcode='42501', message='RIDER_NOT_AVAILABLE: Rider is no longer online and accepting deliveries.';
  end if;

  if exists (
    select 1 from public.delivery_assignments da
    where da.rider_user_id=new.rider_user_id and da.is_current=true
      and da.status in ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery','failed')
  ) then
    raise exception using errcode='23505', message='RIDER_ALREADY_BUSY: A rider can have only one active delivery at a time.';
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.process_delivery_offer_expiries()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_expired record; v_next_profile public.rider_profiles%rowtype;
  v_next_offer_id uuid; v_next_offer_round integer; v_now timestamptz;
  v_processed integer:=0; v_simultaneous_enabled boolean:=false; v_task record;
  v_updated_rows integer:=0;
BEGIN
  FOR v_expired IN
    SELECT dt.id AS delivery_task_id,dt.order_id,dt.branch_id,da.id AS assignment_id,da.rider_user_id
    FROM public.delivery_tasks dt JOIN public.delivery_assignments da ON da.delivery_task_id=dt.id
    WHERE dt.status='assigned' AND da.is_current=true AND da.status='assigned' AND da.accepted_at IS NULL
      AND da.assigned_at<=pg_catalog.clock_timestamp()-interval '60 seconds'
    ORDER BY da.assigned_at FOR UPDATE OF dt,da SKIP LOCKED LIMIT 100
  LOOP
    v_now:=pg_catalog.clock_timestamp();
    PERFORM pg_catalog.set_config('flame_chick.allow_assignment_reassign','on',true);
    UPDATE public.delivery_assignments SET status='reassigned',is_current=false,ended_at=v_now,
      end_reason='No response within 60 seconds'
    WHERE id=v_expired.assignment_id AND is_current=true AND status='assigned' AND accepted_at IS NULL;
    GET DIAGNOSTICS v_updated_rows = ROW_COUNT;
    PERFORM pg_catalog.set_config('flame_chick.allow_assignment_reassign','off',true);
    IF v_updated_rows=0 THEN CONTINUE; END IF;

    UPDATE public.rider_profiles rp SET availability_status=CASE WHEN rp.accepting_jobs=true
      AND rp.last_seen_at>=v_now-interval '4 minutes' THEN 'available' ELSE 'offline' END,updated_at=v_now
    WHERE rp.user_id=v_expired.rider_user_id AND rp.branch_id=v_expired.branch_id
      AND rp.is_active=true AND rp.availability_status<>'suspended'
      AND NOT EXISTS (SELECT 1 FROM public.delivery_assignments da WHERE da.rider_user_id=rp.user_id
        AND da.is_current=true AND da.status IN ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery','failed'));

    SELECT rp.* INTO v_next_profile FROM public.rider_profiles rp
    JOIN public.user_roles ur ON ur.user_id=rp.user_id AND ur.role='rider' AND ur.is_active=true
      AND (ur.branch_id IS NULL OR ur.branch_id=rp.branch_id)
    WHERE rp.branch_id=v_expired.branch_id AND rp.is_active=true AND rp.accepting_jobs=true
      AND rp.availability_status='available' AND rp.last_seen_at>=v_now-interval '4 minutes'
      AND NOT EXISTS (SELECT 1 FROM public.delivery_assignments prior
        WHERE prior.delivery_task_id=v_expired.delivery_task_id AND prior.rider_user_id=rp.user_id)
      AND NOT EXISTS (SELECT 1 FROM public.delivery_assignments active_da
        WHERE active_da.rider_user_id=rp.user_id AND active_da.is_current=true
          AND active_da.status IN ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery','failed'))
      AND NOT EXISTS (SELECT 1 FROM public.delivery_tasks unresolved
        JOIN public.delivery_assignments unresolved_da ON unresolved_da.delivery_task_id=unresolved.id
        WHERE unresolved.branch_id=v_expired.branch_id AND unresolved.status='failed'
          AND unresolved.return_confirmed_at IS NULL AND unresolved_da.rider_user_id=rp.user_id)
      AND NOT EXISTS (SELECT 1 FROM public.delivery_task_offers active_offer
        WHERE active_offer.rider_user_id=rp.user_id AND active_offer.status='offered' AND active_offer.expires_at>v_now)
    ORDER BY (SELECT count(*) FROM public.delivery_assignments recent
      WHERE recent.rider_user_id=rp.user_id AND recent.assigned_at>=v_now-interval '24 hours'
        AND recent.status IN ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery','delivered')) ASC,
      rp.last_seen_at DESC,rp.user_id
    FOR UPDATE OF rp SKIP LOCKED LIMIT 1;

    IF FOUND THEN
      SELECT coalesce(max(dto.offer_round),0)+1 INTO v_next_offer_round
      FROM public.delivery_task_offers dto WHERE dto.delivery_task_id=v_expired.delivery_task_id;
      INSERT INTO public.delivery_task_offers(delivery_task_id,rider_user_id,offer_round,status,offered_at,expires_at)
      VALUES(v_expired.delivery_task_id,v_next_profile.user_id,v_next_offer_round,'offered',v_now,v_now+interval '60 seconds')
      RETURNING id INTO v_next_offer_id;
      INSERT INTO public.delivery_assignments(delivery_task_id,rider_user_id,offer_id,status,is_current,assigned_at)
      VALUES(v_expired.delivery_task_id,v_next_profile.user_id,v_next_offer_id,'assigned',true,v_now);
      UPDATE public.rider_profiles SET availability_status='busy',updated_at=v_now
      WHERE user_id=v_next_profile.user_id AND branch_id=v_expired.branch_id AND is_active=true;
      UPDATE public.delivery_tasks SET status='assigned',assigned_at=v_now,failed_at=NULL,failure_reason=NULL
      WHERE id=v_expired.delivery_task_id;
      INSERT INTO public.order_events(order_id,event_type,actor_user_id,actor_type,payload)
      VALUES(v_expired.order_id,'delivery.assignment_auto_reassigned',NULL,'system',
        pg_catalog.jsonb_build_object('delivery_task_id',v_expired.delivery_task_id,
          'previous_assignment_id',v_expired.assignment_id,'previous_rider_user_id',v_expired.rider_user_id,
          'new_rider_user_id',v_next_profile.user_id,'offer_id',v_next_offer_id,
          'acceptance_expires_at',v_now+interval '60 seconds'));
    ELSE
      UPDATE public.delivery_tasks SET status='dispatch_pending',assigned_at=NULL
      WHERE id=v_expired.delivery_task_id AND status='assigned';
      INSERT INTO public.order_events(order_id,event_type,actor_user_id,actor_type,payload)
      VALUES(v_expired.order_id,'delivery.assignment_expired',NULL,'system',
        pg_catalog.jsonb_build_object('delivery_task_id',v_expired.delivery_task_id,
          'previous_assignment_id',v_expired.assignment_id,'previous_rider_user_id',v_expired.rider_user_id,
          'reason','No response within 60 seconds','manual_reassignment_available',true));
    END IF;
    v_processed:=v_processed+1;
  END LOOP;

  SELECT coalesce(s.simultaneous_offers_enabled,false) INTO v_simultaneous_enabled
  FROM private.delivery_dispatch_settings s WHERE s.singleton=true;
  IF v_simultaneous_enabled THEN
    FOR v_task IN
      SELECT dt.id FROM public.delivery_tasks dt WHERE dt.status='offering'
        AND NOT EXISTS (SELECT 1 FROM public.delivery_task_offers dto
          WHERE dto.delivery_task_id=dt.id AND dto.status='offered' AND dto.expires_at>pg_catalog.now())
      ORDER BY dt.dispatch_started_at NULLS FIRST FOR UPDATE OF dt SKIP LOCKED LIMIT 100
    LOOP
      PERFORM private.start_delivery_offer_round(v_task.id);
      v_processed:=v_processed+1;
    END LOOP;
  END IF;
  RETURN v_processed;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.start_delivery_offer_round(p_delivery_task_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_task public.delivery_tasks%rowtype;
  v_order public.orders%rowtype;
  v_round integer;
  v_count integer := 0;
  v_now timestamptz := pg_catalog.now();
begin
  if not exists (
    select 1 from private.delivery_dispatch_settings s
    where s.singleton = true and s.simultaneous_offers_enabled = true
  ) then
    return 0;
  end if;
  select * into v_task
  from public.delivery_tasks dt
  where dt.id = p_delivery_task_id
  for update;
  if not found then return 0; end if;

  select * into v_order
  from public.orders o
  where o.id = v_task.order_id
  for update;
  if not found or v_order.status <> 'ready' or v_order.fulfillment_type <> 'delivery' then
    return 0;
  end if;

  if v_task.status not in ('dispatch_pending','offering') then return 0; end if;

  if exists (
    select 1 from public.delivery_assignments da
    where da.delivery_task_id = v_task.id and da.is_current = true
  ) then
    return 0;
  end if;

  if exists (
    select 1 from public.delivery_task_offers dto
    where dto.delivery_task_id = v_task.id
      and dto.status = 'offered'
      and dto.expires_at > v_now
  ) then
    update public.delivery_tasks set status = 'offering' where id = v_task.id and status <> 'offering';
    return 0;
  end if;

  update public.delivery_task_offers
  set status = 'expired',
      responded_at = coalesce(responded_at, v_now),
      response_reason = coalesce(response_reason, 'Offer window ended')
  where delivery_task_id = v_task.id
    and status = 'offered'
    and (expires_at is null or expires_at <= v_now);

  select coalesce(max(dto.offer_round), 0) + 1
  into v_round
  from public.delivery_task_offers dto
  where dto.delivery_task_id = v_task.id;

  if v_round > 2 then
    update public.delivery_tasks set status = 'dispatch_pending' where id = v_task.id;
    return 0;
  end if;

  insert into public.delivery_task_offers(
    delivery_task_id, rider_user_id, offer_round, status, offered_at, expires_at
  )
  select
    v_task.id, rp.user_id, v_round, 'offered', v_now, v_now + interval '25 seconds'
  from public.rider_profiles rp
  join public.user_roles ur
    on ur.user_id = rp.user_id
   and ur.role = 'rider'
   and ur.is_active = true
   and (ur.branch_id is null or ur.branch_id = rp.branch_id)
  where rp.branch_id = v_task.branch_id
    and rp.is_active = true
    and rp.accepting_jobs = true
    and rp.availability_status = 'available'
    and rp.last_seen_at >= v_now - interval '4 minutes'
    and not exists (
      select 1
      from public.delivery_assignments active_da
      where active_da.rider_user_id = rp.user_id
        and active_da.is_current = true
        and active_da.status in ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery','failed')
    )
    and not exists (
      select 1
      from public.delivery_tasks unresolved
      join public.delivery_assignments unresolved_da
        on unresolved_da.delivery_task_id = unresolved.id
      where unresolved.branch_id = v_task.branch_id
        and unresolved.status = 'failed'
        and unresolved.return_confirmed_at is null
        and unresolved_da.rider_user_id = rp.user_id
    )
    and not exists (
      select 1
      from public.delivery_task_offers declined
      where declined.delivery_task_id = v_task.id
        and declined.rider_user_id = rp.user_id
        and declined.status = 'rejected'
    )
  on conflict (delivery_task_id, rider_user_id, offer_round) do nothing;

  get diagnostics v_count = row_count;
  if v_count > 0 then
    update public.delivery_tasks set status = 'offering' where id = v_task.id;
  else
    update public.delivery_tasks set status = 'dispatch_pending' where id = v_task.id;
  end if;

  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.start_ready_delivery_offers_for_branch(p_branch_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_task record; v_total integer:=0;
begin
  if not exists (
    select 1 from private.delivery_dispatch_settings s
    where s.singleton = true and s.simultaneous_offers_enabled = true
  ) then
    return 0;
  end if;
  for v_task in
    select dt.id
    from public.delivery_tasks dt
    join public.orders o on o.id=dt.order_id
    where dt.branch_id=p_branch_id and dt.status='dispatch_pending'
      and o.status='ready' and o.fulfillment_type='delivery'
      and not exists(select 1 from public.delivery_assignments da where da.delivery_task_id=dt.id and da.is_current=true)
      and not exists(select 1 from public.delivery_task_offers dto where dto.delivery_task_id=dt.id and dto.status='offered' and dto.expires_at>pg_catalog.now())
      and coalesce((select max(dto.offer_round) from public.delivery_task_offers dto where dto.delivery_task_id=dt.id),0)<2
    order by dt.created_at
    for update of dt skip locked
  loop
    v_total:=v_total+private.start_delivery_offer_round(v_task.id);
  end loop;
  return v_total;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_assignment_offer_response()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_status text; v_reason text;
BEGIN
  IF OLD.status='assigned' AND NEW.status IS DISTINCT FROM OLD.status AND NEW.offer_id IS NOT NULL THEN
    IF NEW.status='accepted' THEN v_status:='accepted'; v_reason:=NULL;
    ELSIF NEW.status='reassigned' THEN
      IF coalesce(NEW.end_reason,'') ILIKE 'No response within 60 seconds%' THEN
        v_status:='expired'; v_reason:='Rider did not respond within 60 seconds';
      ELSIF coalesce(NEW.end_reason,'') ILIKE 'Admin reassigned%' THEN
        v_status:='withdrawn'; v_reason:=NEW.end_reason;
      ELSE v_status:='rejected'; v_reason:=NEW.end_reason;
      END IF;
    ELSE v_status:=NULL;
    END IF;
    IF v_status IS NOT NULL THEN
      UPDATE public.delivery_task_offers SET status=v_status,
        responded_at=coalesce(responded_at,pg_catalog.clock_timestamp()),response_reason=v_reason
      WHERE id=NEW.offer_id AND status='offered';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_delivery_offer_expiry_cron()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_job_id bigint;
BEGIN
  IF NEW.simultaneous_offers_enabled IS NOT DISTINCT FROM OLD.simultaneous_offers_enabled THEN
    RETURN NEW;
  END IF;

  SELECT j.jobid
    INTO v_job_id
  FROM cron.job j
  WHERE j.jobname = 'flame-chick-delivery-offer-expiry'
  LIMIT 1;

  IF v_job_id IS NULL THEN
    RAISE EXCEPTION 'DELIVERY_OFFER_EXPIRY_JOB_MISSING: The scheduled offer expiry job is not registered.';
  END IF;

  PERFORM cron.alter_job(v_job_id, active => NEW.simultaneous_offers_enabled);
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_delivery_task_to_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rider_user_id uuid;
  v_actor_user_id uuid;
  v_actor_type text;
begin
  if new.status is distinct from old.status then
    select da.rider_user_id
      into v_rider_user_id
    from public.delivery_assignments da
    where da.delivery_task_id = new.id
      and da.is_current
    order by da.assigned_at desc
    limit 1;

    v_actor_user_id := coalesce((select auth.uid()), v_rider_user_id);

    v_actor_type := case
      when v_actor_user_id is null then 'system'
      when exists (select 1 from public.rider_profiles rp where rp.user_id = v_actor_user_id) then 'rider'
      when private.has_staff_role(new.branch_id, array['owner','admin']::text[]) then 'admin'
      else 'staff'
    end;

    if new.status in ('picked_up','out_for_delivery') then
      update public.orders
      set status = 'out_for_delivery',
          out_for_delivery_at = coalesce(out_for_delivery_at, now()),
          last_status_changed_by = v_actor_user_id,
          last_status_actor_type = v_actor_type,
          last_status_change_reason = 'Delivery task status: ' || new.status
      where id = new.order_id
        and status not in ('cancelled','rejected','delivered','completed');
    elsif new.status = 'delivered' then
      update public.orders
      set status = 'delivered',
          delivered_at = coalesce(delivered_at, now()),
          last_status_changed_by = v_actor_user_id,
          last_status_actor_type = v_actor_type,
          last_status_change_reason = 'Delivery confirmed by rider'
      where id = new.order_id
        and status not in ('cancelled','rejected','completed');
    elsif new.status = 'failed' then
      insert into public.order_events(order_id, event_type, actor_user_id, actor_type, payload)
      values (
        new.order_id,
        'delivery.failed',
        v_actor_user_id,
        v_actor_type,
        jsonb_build_object('reason', new.failure_reason)
      );
    end if;

    insert into public.event_outbox(event_type, aggregate_type, aggregate_id, payload)
    values (
      'delivery.status_changed',
      'delivery_task',
      new.id,
      jsonb_build_object(
        'delivery_task_id', new.id,
        'order_id', new.order_id,
        'status', new.status
      )
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin new.updated_at := now(); return new; end;
$function$
;

CREATE OR REPLACE FUNCTION public.hfp_accept_delivery_offer(p_offer_id uuid, p_rider_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_task_id uuid;
  v_offer public.delivery_task_offers%rowtype;
  v_task public.delivery_tasks%rowtype;
  v_order public.orders%rowtype;
  v_assignment public.delivery_assignments%rowtype;
  v_profile public.rider_profiles%rowtype;
  v_now timestamptz;
begin
  select dto.delivery_task_id into v_task_id
  from public.delivery_task_offers dto
  where dto.id=p_offer_id and dto.rider_user_id=p_rider_user_id;
  if not found then raise exception using errcode='P0002', message='OFFER_NOT_FOUND: This delivery offer is no longer available.'; end if;

  select * into v_task from public.delivery_tasks dt where dt.id=v_task_id for update;
  if not found then raise exception using errcode='P0002', message='DELIVERY_TASK_NOT_FOUND: This delivery no longer exists.'; end if;

  select * into v_order from public.orders o where o.id=v_task.order_id for update;
  if not found then raise exception using errcode='P0002', message='ORDER_NOT_FOUND: The delivery order no longer exists.'; end if;

  select * into v_profile from public.rider_profiles rp
  where rp.user_id=p_rider_user_id and rp.branch_id=v_task.branch_id
  for update;
  if not found then raise exception using errcode='42501', message='RIDER_PROFILE_REQUIRED: Your active rider profile is missing.'; end if;

  v_now := pg_catalog.clock_timestamp();

  select * into v_offer from public.delivery_task_offers dto
  where dto.id=p_offer_id and dto.delivery_task_id=v_task.id and dto.rider_user_id=p_rider_user_id
  for update;
  if not found or v_offer.status<>'offered' or v_offer.expires_at is null or v_offer.expires_at<=v_now then
    if found and v_offer.status='offered' then
      update public.delivery_task_offers set status='expired',responded_at=coalesce(responded_at,v_now),response_reason='Offer expired' where id=p_offer_id;
    end if;
    raise exception using errcode='22023', message='OFFER_EXPIRED_OR_TAKEN: This offer has expired or another rider has already accepted it.';
  end if;

  if v_order.status<>'ready' or v_task.status<>'offering'
    or exists(select 1 from public.delivery_assignments da where da.delivery_task_id=v_task.id and da.is_current=true) then
    raise exception using errcode='22023', message='OFFER_EXPIRED_OR_TAKEN: This delivery is no longer available.';
  end if;

  if v_profile.is_active is not true or v_profile.accepting_jobs is not true
    or v_profile.availability_status<>'available' or v_profile.last_seen_at is null
    or v_profile.last_seen_at<v_now-interval '4 minutes'
    or exists(select 1 from public.delivery_assignments da where da.rider_user_id=p_rider_user_id and da.is_current=true and da.status in ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery','failed'))
    or exists(
      select 1 from public.delivery_tasks dt
      join public.delivery_assignments da on da.delivery_task_id=dt.id
      where dt.branch_id=v_task.branch_id and dt.status='failed' and dt.return_confirmed_at is null and da.rider_user_id=p_rider_user_id
    )
    or not exists(select 1 from public.user_roles ur where ur.user_id=p_rider_user_id and ur.role='rider' and ur.is_active=true and (ur.branch_id is null or ur.branch_id=v_task.branch_id)) then
    raise exception using errcode='42501', message='RIDER_NOT_AVAILABLE: Your rider status is no longer available. Refresh the app and try again.';
  end if;

  update public.delivery_task_offers set status='accepted',responded_at=v_now,response_reason=null where id=p_offer_id;
  insert into public.delivery_assignments(delivery_task_id,rider_user_id,offer_id,status,is_current,assigned_at,accepted_at)
  values(v_task.id,p_rider_user_id,p_offer_id,'accepted',true,v_now,v_now)
  returning * into v_assignment;

  update public.delivery_tasks set status='accepted',assigned_at=v_now,failed_at=null,failure_reason=null where id=v_task.id;
  update public.rider_profiles set availability_status='busy',updated_at=v_now where user_id=p_rider_user_id and branch_id=v_task.branch_id;

  update public.delivery_task_offers
  set status='withdrawn',responded_at=coalesce(responded_at,v_now),response_reason='Another rider accepted this delivery'
  where status='offered' and id<>p_offer_id and (delivery_task_id=v_task.id or rider_user_id=p_rider_user_id);

  insert into public.order_events(order_id,event_type,actor_user_id,actor_type,payload)
  values(v_order.id,'delivery.rider_accepted',p_rider_user_id,'rider',jsonb_build_object('delivery_task_id',v_task.id,'assignment_id',v_assignment.id,'offer_id',p_offer_id,'offer_round',v_offer.offer_round));

  return jsonb_build_object('ok',true,'delivery_task_id',v_task.id,'assignment_id',v_assignment.id,'offer_id',p_offer_id,'order_number',v_order.order_number,'task_status','accepted','assignment_status','accepted');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.hfp_admin_dashboard(p_branch_id uuid, p_today_start timestamp with time zone, p_today_end timestamp with time zone, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_previous_period_start timestamp with time zone, p_previous_period_end timestamp with time zone, p_week_start timestamp with time zone, p_week_end timestamp with time zone, p_previous_week_start timestamp with time zone, p_previous_week_end timestamp with time zone, p_rush_start timestamp with time zone, p_rush_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='ADMIN_AUTH_REQUIRED: Sign in to view dashboard analytics.';
  END IF;

  IF p_branch_id IS NULL
     OR p_today_start IS NULL OR p_today_end IS NULL OR p_today_start >= p_today_end
     OR p_period_start IS NULL OR p_period_end IS NULL OR p_period_start >= p_period_end
     OR p_previous_period_start IS NULL OR p_previous_period_end IS NULL OR p_previous_period_start >= p_previous_period_end
     OR p_week_start IS NULL OR p_week_end IS NULL OR p_week_start >= p_week_end
     OR p_previous_week_start IS NULL OR p_previous_week_end IS NULL OR p_previous_week_start >= p_previous_week_end
     OR p_rush_start IS NULL OR p_rush_end IS NULL OR p_rush_start >= p_rush_end THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='DASHBOARD_RANGE_INVALID: A valid branch and date range are required.';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id=v_user_id
      AND ur.is_active=true
      AND ur.role IN ('owner','admin','manager')
      AND (ur.branch_id IS NULL OR ur.branch_id=p_branch_id)
  ) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='ADMIN_BRANCH_ACCESS_REQUIRED: You do not have dashboard access to this branch.';
  END IF;

  WITH
  today_rows AS MATERIALIZED (
    SELECT o.id,o.order_number,o.customer_name,o.fulfillment_type,o.status,o.total,o.placed_at,o.created_at
    FROM public.orders o
    WHERE o.branch_id=p_branch_id AND o.placed_at>=p_today_start AND o.placed_at<p_today_end
  ),
  period_rows AS MATERIALIZED (
    SELECT o.id,o.order_number,o.customer_name,o.fulfillment_type,o.status,o.total,o.placed_at,o.created_at
    FROM public.orders o
    WHERE o.branch_id=p_branch_id AND o.placed_at>=p_period_start AND o.placed_at<p_period_end
  ),
  previous_rows AS MATERIALIZED (
    SELECT o.id,o.status,o.total
    FROM public.orders o
    WHERE o.branch_id=p_branch_id AND o.placed_at>=p_previous_period_start AND o.placed_at<p_previous_period_end
  ),
  week_rows AS MATERIALIZED (
    SELECT o.id,o.fulfillment_type,o.status,o.total,o.placed_at
    FROM public.orders o
    WHERE o.branch_id=p_branch_id AND o.placed_at>=p_week_start AND o.placed_at<p_week_end
  ),
  previous_week_rows AS MATERIALIZED (
    SELECT o.id,o.status,o.total
    FROM public.orders o
    WHERE o.branch_id=p_branch_id AND o.placed_at>=p_previous_week_start AND o.placed_at<p_previous_week_end
  ),
  rush_rows AS MATERIALIZED (
    SELECT o.status,o.total,o.placed_at
    FROM public.orders o
    WHERE o.branch_id=p_branch_id AND o.placed_at>=p_rush_start AND o.placed_at<p_rush_end
  ),
  today_status AS (
    SELECT status,count(*)::integer AS orders
    FROM today_rows GROUP BY status
  ),
  period_daily AS (
    SELECT (placed_at AT TIME ZONE 'Asia/Karachi')::date AS local_day,
           count(*) FILTER (WHERE status NOT IN ('cancelled','rejected'))::integer AS orders,
           coalesce(sum(total) FILTER (WHERE status NOT IN ('cancelled','rejected')),0)::numeric AS sales
    FROM period_rows
    GROUP BY 1
  ),
  rush_hourly AS (
    SELECT extract(hour FROM placed_at AT TIME ZONE 'Asia/Karachi')::integer AS local_hour,
           count(*)::integer AS orders,
           coalesce(sum(total) FILTER (WHERE status NOT IN ('cancelled','rejected')),0)::numeric AS sales
    FROM rush_rows
    GROUP BY 1
  )
  SELECT jsonb_build_object(
    'updated_at',pg_catalog.clock_timestamp(),

    'today',(
      SELECT jsonb_build_object(
        'orders',count(*)::integer,
        'sales',coalesce(sum(total) FILTER (WHERE status NOT IN ('cancelled','rejected')),0),
        'gross_order_value',coalesce(sum(total),0),
        'delivery',count(*) FILTER (WHERE fulfillment_type='delivery'),
        'takeaway',count(*) FILTER (WHERE fulfillment_type IN ('pickup','takeaway')),
        'dine_in',count(*) FILTER (WHERE fulfillment_type IN ('dine_in','dine-in')),
        'pending',count(*) FILTER (WHERE status='new'),
        'preparing',count(*) FILTER (WHERE status IN ('accepted','preparing')),
        'ready',count(*) FILTER (WHERE status='ready'),
        'out_for_delivery',count(*) FILTER (WHERE status='out_for_delivery'),
        'completed',count(*) FILTER (WHERE status IN ('delivered','collected','served','completed')),
        'status',coalesce((SELECT jsonb_object_agg(status,orders) FROM today_status),'{}'::jsonb)
      )
      FROM today_rows
    ),

    'period',(
      SELECT jsonb_build_object(
        'orders',count(*) FILTER (WHERE status NOT IN ('cancelled','rejected')),
        'gross_orders',count(*),
        'sales',coalesce(sum(total) FILTER (WHERE status NOT IN ('cancelled','rejected')),0),
        'gross_order_value',coalesce(sum(total),0),
        'average_order_value',
          CASE WHEN count(*) FILTER (WHERE status NOT IN ('cancelled','rejected'))=0 THEN 0
          ELSE coalesce(sum(total) FILTER (WHERE status NOT IN ('cancelled','rejected')),0)
             / (count(*) FILTER (WHERE status NOT IN ('cancelled','rejected'))) END,
        'daily',(
          SELECT coalesce(jsonb_agg(jsonb_build_object(
            'day',d.local_day::date,
            'orders',coalesce(pd.orders,0),
            'sales',coalesce(pd.sales,0)
          ) ORDER BY d.local_day),'[]'::jsonb)
          FROM pg_catalog.generate_series(
            (p_period_start AT TIME ZONE 'Asia/Karachi')::date,
            ((p_period_end - interval '1 microsecond') AT TIME ZONE 'Asia/Karachi')::date,
            interval '1 day'
          ) AS d(local_day)
          LEFT JOIN period_daily pd ON pd.local_day=d.local_day
        )
      )
      FROM period_rows
    ),

    'previous_period',(
      SELECT jsonb_build_object(
        'orders',count(*) FILTER (WHERE status NOT IN ('cancelled','rejected')),
        'sales',coalesce(sum(total) FILTER (WHERE status NOT IN ('cancelled','rejected')),0),
        'gross_order_value',coalesce(sum(total),0),
        'average_order_value',
          CASE WHEN count(*) FILTER (WHERE status NOT IN ('cancelled','rejected'))=0 THEN 0
          ELSE coalesce(sum(total) FILTER (WHERE status NOT IN ('cancelled','rejected')),0)
             / (count(*) FILTER (WHERE status NOT IN ('cancelled','rejected'))) END
      )
      FROM previous_rows
    ),

    'week',(
      SELECT jsonb_build_object(
        'start',p_week_start,
        'end',p_week_end,
        'orders',count(*) FILTER (WHERE status NOT IN ('cancelled','rejected')),
        'sales',coalesce(sum(total) FILTER (WHERE status NOT IN ('cancelled','rejected')),0),
        'average_order_value',
          CASE WHEN count(*) FILTER (WHERE status NOT IN ('cancelled','rejected'))=0 THEN 0
          ELSE coalesce(sum(total) FILTER (WHERE status NOT IN ('cancelled','rejected')),0)
             / (count(*) FILTER (WHERE status NOT IN ('cancelled','rejected'))) END,
        'delivery',count(*) FILTER (WHERE fulfillment_type='delivery' AND status NOT IN ('cancelled','rejected')),
        'takeaway',count(*) FILTER (WHERE fulfillment_type IN ('pickup','takeaway') AND status NOT IN ('cancelled','rejected')),
        'dine_in',count(*) FILTER (WHERE fulfillment_type IN ('dine_in','dine-in') AND status NOT IN ('cancelled','rejected'))
      )
      FROM week_rows
    ),

    'previous_week',(
      SELECT jsonb_build_object(
        'orders',count(*) FILTER (WHERE status NOT IN ('cancelled','rejected')),
        'sales',coalesce(sum(total) FILTER (WHERE status NOT IN ('cancelled','rejected')),0),
        'average_order_value',
          CASE WHEN count(*) FILTER (WHERE status NOT IN ('cancelled','rejected'))=0 THEN 0
          ELSE coalesce(sum(total) FILTER (WHERE status NOT IN ('cancelled','rejected')),0)
             / (count(*) FILTER (WHERE status NOT IN ('cancelled','rejected'))) END
      )
      FROM previous_week_rows
    ),

    'rush_hours',(
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'hour',h.local_hour,
        'orders',coalesce(rh.orders,0),
        'sales',coalesce(rh.sales,0)
      ) ORDER BY h.local_hour),'[]'::jsonb)
      FROM pg_catalog.generate_series(11,23) AS h(local_hour)
      LEFT JOIN rush_hourly rh ON rh.local_hour=h.local_hour
    ),

    'recent_orders',(
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id',r.id,'order_number',r.order_number,'customer_name',r.customer_name,
        'fulfillment_type',r.fulfillment_type,'status',r.status,'total',r.total,
        'placed_at',r.placed_at
      ) ORDER BY r.placed_at DESC),'[]'::jsonb)
      FROM (
        SELECT o.id,o.order_number,o.customer_name,o.fulfillment_type,o.status,o.total,o.placed_at
        FROM public.orders o
        WHERE o.branch_id=p_branch_id
        ORDER BY o.placed_at DESC LIMIT 8
      ) r
    ),

    'attention_orders',(
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id',a.id,'order_number',a.order_number,'customer_name',a.customer_name,
        'fulfillment_type',a.fulfillment_type,'status',a.status,'total',a.total,
        'placed_at',a.placed_at,
        'age_minutes',floor(extract(epoch FROM (pg_catalog.now()-a.placed_at))/60)::integer
      ) ORDER BY a.placed_at ASC),'[]'::jsonb)
      FROM (
        SELECT o.id,o.order_number,o.customer_name,o.fulfillment_type,o.status,o.total,o.placed_at
        FROM public.orders o
        WHERE o.branch_id=p_branch_id
          AND (
            (o.status='new' AND o.placed_at<pg_catalog.now()-interval '15 minutes')
            OR (o.status IN ('accepted','preparing') AND o.placed_at<pg_catalog.now()-interval '30 minutes')
            OR (o.status='ready' AND o.placed_at<pg_catalog.now()-interval '20 minutes')
            OR (o.status='out_for_delivery' AND o.placed_at<pg_catalog.now()-interval '45 minutes')
          )
        ORDER BY o.placed_at ASC LIMIT 8
      ) a
    )
  )
  INTO v_result;

  RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.hfp_admin_reassign_delivery(p_delivery_task_id uuid, p_rider_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor_id uuid:=auth.uid(); v_actor_role text;
  v_task public.delivery_tasks%rowtype; v_order public.orders%rowtype;
  v_old_assignment public.delivery_assignments%rowtype;
  v_new_profile public.rider_profiles%rowtype;
  v_offer_id uuid; v_offer_round integer; v_now timestamptz:=pg_catalog.clock_timestamp();
BEGIN
  IF v_actor_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='STAFF_AUTH_REQUIRED: Sign in before reassigning a delivery.'; END IF;
  IF p_delivery_task_id IS NULL OR p_rider_user_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='REASSIGN_REQUEST_INVALID: Delivery and rider are required.'; END IF;
  SELECT * INTO v_task FROM public.delivery_tasks dt WHERE dt.id=p_delivery_task_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='DELIVERY_TASK_NOT_FOUND: Delivery was not found.'; END IF;
  SELECT * INTO v_order FROM public.orders o WHERE o.id=v_task.order_id FOR UPDATE;
  IF NOT FOUND OR v_order.fulfillment_type<>'delivery' OR v_order.status<>'ready' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='DELIVERY_NOT_READY: Only a ready delivery can be reassigned.';
  END IF;
  SELECT ur.role INTO v_actor_role FROM public.user_roles ur
  WHERE ur.user_id=v_actor_id AND ur.is_active=true AND (ur.branch_id IS NULL OR ur.branch_id=v_task.branch_id)
    AND ur.role IN ('owner','admin','manager','cashier')
  ORDER BY CASE ur.role WHEN 'owner' THEN 1 WHEN 'admin' THEN 2 WHEN 'manager' THEN 3 ELSE 4 END LIMIT 1;
  IF v_actor_role IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='DISPATCH_ROLE_REQUIRED: Only authorized staff can reassign deliveries.'; END IF;
  SELECT * INTO v_old_assignment FROM public.delivery_assignments da
  WHERE da.delivery_task_id=v_task.id AND da.is_current=true
  ORDER BY da.assigned_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND OR v_task.status<>'assigned' OR v_old_assignment.status<>'assigned' OR v_old_assignment.accepted_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='REASSIGN_NOT_PENDING: This delivery is no longer waiting for rider acceptance.';
  END IF;
  IF v_old_assignment.rider_user_id=p_rider_user_id THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='REASSIGN_DIFFERENT_RIDER: Choose a different rider.';
  END IF;
  SELECT * INTO v_new_profile FROM public.rider_profiles rp
  WHERE rp.user_id=p_rider_user_id AND rp.branch_id=v_task.branch_id AND rp.is_active=true FOR UPDATE;
  IF NOT FOUND OR v_new_profile.accepting_jobs IS NOT TRUE OR v_new_profile.availability_status<>'available'
     OR v_new_profile.last_seen_at IS NULL OR v_new_profile.last_seen_at<v_now-interval '4 minutes'
     OR NOT EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id=p_rider_user_id AND ur.role='rider'
       AND ur.is_active=true AND (ur.branch_id IS NULL OR ur.branch_id=v_task.branch_id))
     OR EXISTS (SELECT 1 FROM public.delivery_assignments da WHERE da.rider_user_id=p_rider_user_id
       AND da.is_current=true AND da.status IN ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery','failed'))
     OR EXISTS (SELECT 1 FROM public.delivery_tasks unresolved
       JOIN public.delivery_assignments uda ON uda.delivery_task_id=unresolved.id
       WHERE unresolved.branch_id=v_task.branch_id AND unresolved.status='failed'
         AND unresolved.return_confirmed_at IS NULL AND uda.rider_user_id=p_rider_user_id) THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='RIDER_NOT_AVAILABLE: Choose a different active, online and available rider for this branch.';
  END IF;
  PERFORM pg_catalog.set_config('flame_chick.allow_assignment_reassign','on',true);
  UPDATE public.delivery_assignments SET status='reassigned',is_current=false,ended_at=v_now,
    end_reason='Admin reassigned before rider acceptance'
  WHERE id=v_old_assignment.id AND is_current=true AND status='assigned';
  PERFORM pg_catalog.set_config('flame_chick.allow_assignment_reassign','off',true);
  UPDATE public.rider_profiles rp SET availability_status=CASE WHEN rp.accepting_jobs=true
    AND rp.last_seen_at>=v_now-interval '4 minutes' THEN 'available' ELSE 'offline' END,updated_at=v_now
  WHERE rp.user_id=v_old_assignment.rider_user_id AND rp.branch_id=v_task.branch_id
    AND rp.is_active=true AND rp.availability_status<>'suspended'
    AND NOT EXISTS (SELECT 1 FROM public.delivery_assignments da WHERE da.rider_user_id=rp.user_id
      AND da.is_current=true AND da.status IN ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery','failed'));
  SELECT coalesce(max(dto.offer_round),0)+1 INTO v_offer_round FROM public.delivery_task_offers dto
  WHERE dto.delivery_task_id=v_task.id;
  INSERT INTO public.delivery_task_offers(delivery_task_id,rider_user_id,offer_round,status,offered_at,expires_at)
  VALUES(v_task.id,p_rider_user_id,v_offer_round,'offered',v_now,v_now+interval '60 seconds') RETURNING id INTO v_offer_id;
  INSERT INTO public.delivery_assignments(delivery_task_id,rider_user_id,offer_id,status,is_current,assigned_at)
  VALUES(v_task.id,p_rider_user_id,v_offer_id,'assigned',true,v_now);
  UPDATE public.rider_profiles SET availability_status='busy',updated_at=v_now
  WHERE user_id=p_rider_user_id AND branch_id=v_task.branch_id;
  UPDATE public.delivery_tasks SET status='assigned',assigned_at=v_now WHERE id=v_task.id;
  INSERT INTO public.order_events(order_id,event_type,actor_user_id,actor_type,payload)
  VALUES(v_order.id,'delivery.rider_reassigned',v_actor_id,
    CASE WHEN v_actor_role IN ('owner','admin') THEN 'admin' ELSE 'staff' END,
    pg_catalog.jsonb_build_object('delivery_task_id',v_task.id,'previous_assignment_id',v_old_assignment.id,
      'previous_rider_user_id',v_old_assignment.rider_user_id,'rider_user_id',p_rider_user_id,
      'offer_id',v_offer_id,'acceptance_expires_at',v_now+interval '60 seconds'));
  RETURN pg_catalog.jsonb_build_object('ok',true,'delivery_task_id',v_task.id,'offer_id',v_offer_id,
    'rider_user_id',p_rider_user_id,'task_status','assigned','assignment_status','assigned',
    'acceptance_expires_at',v_now+interval '60 seconds');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.hfp_check_website_order_rate_limit(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_phone_raw text;
  v_phone text;
  v_phone_hash text;
  v_ip inet;
  v_ip_hash text;
  v_request_key text;
  v_request_hash text;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_phone_lock bigint;
  v_ip_lock bigint;
  v_phone_count_10m integer := 0;
  v_phone_count_1h integer := 0;
  v_ip_count_10m integer := 0;
  v_ip_count_1h integer := 0;
  v_phone_oldest_10m timestamptz;
  v_phone_oldest_1h timestamptz;
  v_ip_oldest_10m timestamptz;
  v_ip_oldest_1h timestamptz;
  v_retry_after integer := 0;
  v_wait numeric;
begin
  if p_payload is null or pg_catalog.jsonb_typeof(p_payload) is distinct from 'object' then
    raise exception using errcode = '22023', message = 'RATE_LIMIT_REQUEST_INVALID: Rate-limit request must be a JSON object.';
  end if;

  v_phone_raw := coalesce(p_payload #>> '{customer,phone}', p_payload->>'customer_phone', '');
  v_request_key := nullif(pg_catalog.btrim(p_payload->>'idempotency_key'), '');

  if v_request_key is null or pg_catalog.length(v_request_key) < 16 or pg_catalog.length(v_request_key) > 160 then
    raise exception using errcode = '22023', message = 'IDEMPOTENCY_REQUIRED: A 16-160 character idempotency_key is required.';
  end if;

  v_phone := pg_catalog.regexp_replace(coalesce(v_phone_raw, ''), '[^0-9]', '', 'g');
  if pg_catalog.length(v_phone) = 12 and pg_catalog.left(v_phone, 2) = '92' then
    v_phone := '0' || pg_catalog.substr(v_phone, 3);
  elsif pg_catalog.length(v_phone) = 10 and pg_catalog.left(v_phone, 1) = '3' then
    v_phone := '0' || v_phone;
  end if;

  if pg_catalog.length(v_phone) < 7 or pg_catalog.length(v_phone) > 20 then
    raise exception using errcode = '22023', message = 'CUSTOMER_PHONE_REQUIRED: A valid customer phone number is required.';
  end if;

  v_phone_hash := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(v_phone, 'UTF8'), 'sha256'),
    'hex'
  );
  -- Exact client retry (same idempotency key and same normalized request) is free;
  -- changed order details create a new request fingerprint and count separately.
  v_request_hash := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to((p_payload - 'client_ip')::text, 'UTF8'), 'sha256'),
    'hex'
  );

  begin
    v_ip := nullif(pg_catalog.btrim(p_payload->>'client_ip'), '')::inet;
  exception when others then
    v_ip := null;
  end;

  if v_ip is not null then
    v_ip_hash := pg_catalog.encode(
      extensions.digest(pg_catalog.convert_to(v_ip::text, 'UTF8'), 'sha256'),
      'hex'
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('hfp-website-request:' || v_request_hash, 0)
  );

  if exists (
    select 1
    from private.hfp_website_order_rate_limit_events e
    where e.request_hash = v_request_hash
  ) then
    return pg_catalog.jsonb_build_object('allowed', true, 'idempotent_replay', true, 'retry_after_seconds', 0);
  end if;

  v_phone_lock := pg_catalog.hashtextextended('hfp-website-phone:' || v_phone_hash, 0);
  if v_ip_hash is not null then
    v_ip_lock := pg_catalog.hashtextextended('hfp-website-ip:' || v_ip_hash, 0);
    if v_phone_lock < v_ip_lock then
      perform pg_catalog.pg_advisory_xact_lock(v_phone_lock);
      perform pg_catalog.pg_advisory_xact_lock(v_ip_lock);
    else
      perform pg_catalog.pg_advisory_xact_lock(v_ip_lock);
      perform pg_catalog.pg_advisory_xact_lock(v_phone_lock);
    end if;
  else
    perform pg_catalog.pg_advisory_xact_lock(v_phone_lock);
  end if;

  delete from private.hfp_website_order_rate_limit_events e
  where e.requested_at < v_now - interval '24 hours';

  select count(*)::integer, min(e.requested_at)
    into v_phone_count_10m, v_phone_oldest_10m
  from private.hfp_website_order_rate_limit_events e
  where e.phone_hash = v_phone_hash and e.requested_at > v_now - interval '10 minutes';

  select count(*)::integer, min(e.requested_at)
    into v_phone_count_1h, v_phone_oldest_1h
  from private.hfp_website_order_rate_limit_events e
  where e.phone_hash = v_phone_hash and e.requested_at > v_now - interval '1 hour';

  if v_phone_count_10m >= 3 then
    v_wait := ceil(extract(epoch from (v_phone_oldest_10m + interval '10 minutes' - v_now)));
    v_retry_after := greatest(v_retry_after, coalesce(v_wait, 1)::integer);
  end if;
  if v_phone_count_1h >= 10 then
    v_wait := ceil(extract(epoch from (v_phone_oldest_1h + interval '1 hour' - v_now)));
    v_retry_after := greatest(v_retry_after, coalesce(v_wait, 1)::integer);
  end if;

  if v_ip_hash is not null then
    select count(*)::integer, min(e.requested_at)
      into v_ip_count_10m, v_ip_oldest_10m
    from private.hfp_website_order_rate_limit_events e
    where e.ip_hash = v_ip_hash and e.requested_at > v_now - interval '10 minutes';

    select count(*)::integer, min(e.requested_at)
      into v_ip_count_1h, v_ip_oldest_1h
    from private.hfp_website_order_rate_limit_events e
    where e.ip_hash = v_ip_hash and e.requested_at > v_now - interval '1 hour';

    if v_ip_count_10m >= 20 then
      v_wait := ceil(extract(epoch from (v_ip_oldest_10m + interval '10 minutes' - v_now)));
      v_retry_after := greatest(v_retry_after, coalesce(v_wait, 1)::integer);
    end if;
    if v_ip_count_1h >= 60 then
      v_wait := ceil(extract(epoch from (v_ip_oldest_1h + interval '1 hour' - v_now)));
      v_retry_after := greatest(v_retry_after, coalesce(v_wait, 1)::integer);
    end if;
  end if;

  if v_retry_after > 0 then
    return pg_catalog.jsonb_build_object('allowed', false, 'code', 'RATE_LIMITED', 'retry_after_seconds', v_retry_after);
  end if;

  insert into private.hfp_website_order_rate_limit_events(request_hash, phone_hash, ip_hash, requested_at)
  values (v_request_hash, v_phone_hash, v_ip_hash, v_now)
  on conflict (request_hash) do nothing;

  return pg_catalog.jsonb_build_object('allowed', true, 'idempotent_replay', false, 'retry_after_seconds', 0);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.hfp_create_order(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_restaurant_id uuid;
  v_branch_id uuid;
  v_source text;
  v_fulfillment text;
  v_idempotency_key text;
  v_request_hash text;
  v_existing public.orders%rowtype;
  v_order public.orders%rowtype;
  v_order_id uuid;
  v_order_number text;
  v_actor_user_id uuid;
  v_actor_role text;
  v_customer jsonb;
  v_delivery jsonb;
  v_customer_name text;
  v_customer_phone text;
  v_customer_email text;
  v_address text;
  v_delivery_instructions text;
  v_delivery_area_id uuid;
  v_delivery_area_name text;
  v_delivery_fee numeric(12,2) := 0;
  v_delivery_lat numeric(10,7);
  v_delivery_lng numeric(10,7);
  v_table_id uuid;
  v_table_number text;
  v_payment_method text;
  v_notes text;
  v_items jsonb;
  v_item jsonb;
  v_modifiers jsonb;
  v_modifier jsonb;
  v_choices jsonb;
  v_item_id uuid;
  v_line_number integer := 0;
  v_qty integer;
  v_subtotal numeric(12,2) := 0;
  v_base_price numeric(12,2);
  v_modifier_total numeric(12,2);
  v_modifier_price numeric(12,2);
  v_line_total numeric(12,2);
  v_product_id uuid;
  v_variant_id uuid;
  v_deal_id uuid;
  v_group_id uuid;
  v_modifier_id uuid;
  v_selected_count integer;
  v_group record;
  v_mod record;
  v_product record;
  v_variant public.product_variants%rowtype;
  v_deal public.deals%rowtype;
  v_component record;
  v_selected_product_id uuid;
  v_selected_variant_id uuid;
  v_selected_product_name text;
  v_selected_variant_label text;
  v_component_name text;
  v_component_volume text;
  v_component_snapshot jsonb;
  v_component_qty integer;
  v_currency text := 'PKR';
  v_line_kind text;
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception using errcode = '22023', message = 'INVALID_REQUEST: Request body must be a JSON object.';
  end if;

  v_source := lower(coalesce(p_payload->>'source', ''));
  if v_source not in ('website','pos','whatsapp','phone','third_party','manual','other') then
    raise exception using errcode = '22023', message = 'INVALID_SOURCE: Unsupported order source.';
  end if;

  v_fulfillment := lower(coalesce(p_payload->>'fulfillment_type', ''));
  if v_fulfillment not in ('delivery','pickup','dine_in') then
    raise exception using errcode = '22023', message = 'INVALID_FULFILLMENT: Fulfilment must be delivery, pickup, or dine_in.';
  end if;

  v_idempotency_key := nullif(btrim(p_payload->>'idempotency_key'), '');
  if v_idempotency_key is null or length(v_idempotency_key) < 16 or length(v_idempotency_key) > 160 then
    raise exception using errcode = '22023', message = 'IDEMPOTENCY_REQUIRED: A 16-160 character idempotency_key is required.';
  end if;
  v_request_hash := md5(p_payload::text);

  select r.id, b.id, r.currency_code
    into v_restaurant_id, v_branch_id, v_currency
  from public.restaurants r
  join public.branches b on b.restaurant_id = r.id
  where r.slug = 'flame-chick'
    and r.is_active = true
    and b.branch_code = 'MAIN'
    and b.is_active = true
  order by b.created_at
  limit 1;

  if v_branch_id is null then
    raise exception using errcode = 'P0002', message = 'FLAME_CHICK_BRANCH_NOT_FOUND: Active Flame Chick main branch was not found.';
  end if;

  -- Serialize requests sharing the same branch/source/key so concurrent retries cannot duplicate an order.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_branch_id::text || '|' || v_source || '|' || v_idempotency_key, 0)
  );

  select * into v_existing
  from public.orders
  where branch_id = v_branch_id
    and source = v_source
    and idempotency_key = v_idempotency_key;

  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception using errcode = '23505', message = 'IDEMPOTENCY_KEY_REUSED: This idempotency key was already used with a different request.';
    end if;
    return jsonb_build_object(
      'ok', true,
      'idempotent_replay', true,
      'order', jsonb_build_object(
        'id', v_existing.id,
        'order_number', v_existing.order_number,
        'status', v_existing.status,
        'fulfillment_type', v_existing.fulfillment_type,
        'subtotal', v_existing.subtotal,
        'delivery_fee', v_existing.delivery_fee,
        'total', v_existing.total,
        'currency_code', v_existing.currency_code,
        'payment_status', v_existing.payment_status
      )
    );
  end if;

  v_customer := coalesce(p_payload->'customer', '{}'::jsonb);
  v_delivery := coalesce(p_payload->'delivery', '{}'::jsonb);
  if jsonb_typeof(v_customer) <> 'object' or jsonb_typeof(v_delivery) <> 'object' then
    raise exception using errcode = '22023', message = 'INVALID_CUSTOMER: Customer and delivery details must be JSON objects.';
  end if;

  v_customer_name := nullif(btrim(v_customer->>'name'), '');
  v_customer_phone := nullif(btrim(v_customer->>'phone'), '');
  v_customer_email := nullif(btrim(v_customer->>'email'), '');
  if v_customer_name is null or length(v_customer_name) > 120 then
    raise exception using errcode = '22023', message = 'CUSTOMER_NAME_REQUIRED: Customer name is required and must be 120 characters or fewer.';
  end if;
  if v_customer_phone is null or length(v_customer_phone) > 30 then
    raise exception using errcode = '22023', message = 'CUSTOMER_PHONE_REQUIRED: A valid customer phone number is required.';
  end if;
  if v_customer_email is not null and length(v_customer_email) > 254 then
    raise exception using errcode = '22023', message = 'CUSTOMER_EMAIL_INVALID: Customer email is too long.';
  end if;

  v_payment_method := lower(coalesce(p_payload->>'payment_method', case when v_source = 'website' then 'cod' else 'cash' end));
  if v_payment_method not in ('cash','card','bank_transfer','wallet','online','cod','other') then
    raise exception using errcode = '22023', message = 'PAYMENT_METHOD_INVALID: Unsupported payment method.';
  end if;

  v_notes := nullif(btrim(p_payload->>'notes'), '');
  if v_notes is not null and length(v_notes) > 1000 then
    raise exception using errcode = '22023', message = 'ORDER_NOTES_TOO_LONG: Order notes must be 1000 characters or fewer.';
  end if;

  if v_fulfillment = 'delivery' then
    v_address := nullif(btrim(v_delivery->>'address'), '');
    if v_address is null or length(v_address) > 600 then
      raise exception using errcode = '22023', message = 'DELIVERY_ADDRESS_REQUIRED: Delivery address is required and must be 600 characters or fewer.';
    end if;
    v_delivery_area_id := nullif(v_delivery->>'area_id','')::uuid;
    if v_delivery_area_id is null then
      -- Flame Chick demo: accept a manually entered address without a configured zone.
      v_delivery_area_name := 'Manual address (demo)';
      v_delivery_fee := 0;
    else
      select da.name, da.delivery_fee
        into v_delivery_area_name, v_delivery_fee
      from public.delivery_areas da
      where da.id = v_delivery_area_id
        and da.restaurant_id = v_restaurant_id
        and da.branch_id = v_branch_id
        and da.is_active = true;

      if not found then
        raise exception using errcode = '22023', message = 'DELIVERY_AREA_UNAVAILABLE: Selected delivery area is unavailable.';
      end if;
    end if;

    v_delivery_instructions := nullif(btrim(v_delivery->>'instructions'), '');
    if v_delivery_instructions is not null and length(v_delivery_instructions) > 600 then
      raise exception using errcode = '22023', message = 'DELIVERY_INSTRUCTIONS_TOO_LONG: Delivery instructions must be 600 characters or fewer.';
    end if;
    if nullif(v_delivery->>'latitude','') is not null then
      v_delivery_lat := (v_delivery->>'latitude')::numeric;
      if v_delivery_lat < -90 or v_delivery_lat > 90 then
        raise exception using errcode = '22023', message = 'DELIVERY_COORDINATES_INVALID: Latitude is outside its valid range.';
      end if;
    end if;
    if nullif(v_delivery->>'longitude','') is not null then
      v_delivery_lng := (v_delivery->>'longitude')::numeric;
      if v_delivery_lng < -180 or v_delivery_lng > 180 then
        raise exception using errcode = '22023', message = 'DELIVERY_COORDINATES_INVALID: Longitude is outside its valid range.';
      end if;
    end if;
  elsif v_fulfillment = 'dine_in' then
    v_table_id := nullif(p_payload->>'table_id','')::uuid;
    if v_table_id is null then
      raise exception using errcode = '22023', message = 'TABLE_REQUIRED: Select a restaurant table for dine-in.';
    end if;
    select rt.table_number into v_table_number
    from public.restaurant_tables rt
    where rt.id = v_table_id and rt.branch_id = v_branch_id and rt.is_active = true;
    if not found then
      raise exception using errcode = '22023', message = 'TABLE_UNAVAILABLE: Selected table is unavailable.';
    end if;
  end if;

  v_items := p_payload->'items';
  if v_items is null or jsonb_typeof(v_items) is distinct from 'array' or jsonb_array_length(v_items) < 1 or jsonb_array_length(v_items) > 40 then
    raise exception using errcode = '22023', message = 'ORDER_ITEMS_INVALID: Order must contain between 1 and 40 line items.';
  end if;

  v_actor_user_id := nullif(p_payload->>'actor_user_id','')::uuid;
  if v_source in ('pos','whatsapp','phone','third_party','manual','other') then
    if v_actor_user_id is null then
      raise exception using errcode = '42501', message = 'STAFF_AUTH_REQUIRED: A signed-in staff member is required for this order source.';
    end if;
    select ur.role into v_actor_role
    from public.user_roles ur
    where ur.user_id = v_actor_user_id
      and ur.is_active = true
      and ur.role in ('owner','admin','manager','cashier')
      and (ur.branch_id is null or ur.branch_id = v_branch_id)
    order by case ur.role when 'owner' then 1 when 'admin' then 2 when 'manager' then 3 else 4 end
    limit 1;
    if v_actor_role is null then
      raise exception using errcode = '42501', message = 'STAFF_ROLE_REQUIRED: This staff account cannot create orders.';
    end if;
  end if;

  v_order_number := 'PB-' ||
    pg_catalog.to_char(pg_catalog.now() at time zone 'Asia/Karachi', 'YYMMDD') || '-' ||
    pg_catalog.lpad(pg_catalog.nextval('public.hfp_order_number_seq')::text, 5, '0');

  insert into public.orders (
    branch_id, order_number, local_order_id, idempotency_key, request_hash,
    source, source_reference, fulfillment_type, status,
    customer_name, customer_phone, customer_email,
    delivery_address, delivery_area_id, delivery_area_name_snapshot,
    delivery_area_fee_snapshot, delivery_latitude, delivery_longitude, delivery_instructions,
    table_id, table_number_snapshot,
    subtotal, discount_amount, tax_amount, service_charge, delivery_fee, tip_amount,
    total, paid_amount, balance_due, currency_code, payment_status, payment_method_summary,
    notes, promo_snapshot, address_snapshot, source_payload_snapshot,
    cashier_id, last_status_changed_by, last_status_actor_type
  ) values (
    v_branch_id, v_order_number, nullif(p_payload->>'local_order_id',''), v_idempotency_key, v_request_hash,
    v_source, nullif(p_payload->>'source_reference',''), v_fulfillment, 'new',
    v_customer_name, v_customer_phone, v_customer_email,
    v_address, v_delivery_area_id, v_delivery_area_name,
    v_delivery_fee, v_delivery_lat, v_delivery_lng, v_delivery_instructions,
    v_table_id, v_table_number,
    0, 0, 0, 0, v_delivery_fee, 0,
    v_delivery_fee, 0, v_delivery_fee, v_currency, 'unpaid', v_payment_method,
    v_notes, '{}'::jsonb,
    jsonb_build_object('address', v_address, 'area_name', v_delivery_area_name, 'area_fee', v_delivery_fee, 'table_number', v_table_number),
    jsonb_build_object('client_schema', 'hfp-order-v1', 'local_order_id', nullif(p_payload->>'local_order_id','')),
    case when v_source = 'pos' then v_actor_user_id else null end,
    null, null
  ) returning id into v_order_id;

  for v_item in select value from jsonb_array_elements(v_items)
  loop
    v_line_number := v_line_number + 1;
    v_qty := coalesce(nullif(v_item->>'quantity','')::integer, 1);
    if v_qty < 1 or v_qty > 40 then
      raise exception using errcode = '22023', message = 'ITEM_QUANTITY_INVALID: Each line quantity must be between 1 and 40.';
    end if;

    v_line_kind := lower(coalesce(v_item->>'kind','product'));

    if v_line_kind = 'product' then
      v_product_id := nullif(v_item->>'product_id','')::uuid;
      v_variant_id := nullif(v_item->>'variant_id','')::uuid;
      if v_product_id is null or v_variant_id is null then
        raise exception using errcode = '22023', message = 'PRODUCT_VARIANT_REQUIRED: Product and selected variant are required.';
      end if;

      select p.*, v.id as selected_variant_id, v.size_key as selected_size_key,
             v.size_label as selected_size_label, v.price as selected_price
      into v_product
      from public.products p
      join public.product_variants v on v.product_id = p.id
      where p.id = v_product_id
        and v.id = v_variant_id
        and p.restaurant_id = v_restaurant_id
        and p.is_active = true and p.is_available = true
        and v.is_active = true and v.is_available = true;

      if not found then
        raise exception using errcode = '22023', message = 'PRODUCT_UNAVAILABLE: One of the selected products or variants is no longer available.';
      end if;

      v_base_price := (to_jsonb(v_product)->>'selected_price')::numeric;
      v_modifiers := coalesce(v_item->'modifiers', '[]'::jsonb);
      if jsonb_typeof(v_modifiers) <> 'array' or jsonb_array_length(v_modifiers) > 20 then
        raise exception using errcode = '22023', message = 'MODIFIERS_INVALID: Modifier selections must be an array of at most 20 selections.';
      end if;

      -- Enforce each product's configured minimum and maximum selections.
      for v_group in
        select mg.id, mg.name_en, mg.min_select, mg.max_select
        from public.modifier_group_assignments a
        join public.modifier_groups mg on mg.id = a.modifier_group_id
        where a.product_id = v_product_id and a.is_active = true and mg.is_active = true
      loop
        select count(*) into v_selected_count
        from jsonb_array_elements(v_modifiers) sel(value)
        where sel.value->>'group_id' = v_group.id::text;
        if v_selected_count < v_group.min_select then
          raise exception using errcode = '22023', message = 'MODIFIER_REQUIRED: Select the required option for ' || v_group.name_en || '.';
        end if;
        if v_selected_count > v_group.max_select then
          raise exception using errcode = '22023', message = 'MODIFIER_LIMIT_EXCEEDED: Too many selections for ' || v_group.name_en || '.';
        end if;
      end loop;

      insert into public.order_items (
        order_id, line_number, product_id, product_variant_id, quantity,
        product_name_snapshot, variant_label_snapshot, unit_price_snapshot,
        discount_amount, tax_amount, line_total, item_notes, item_snapshot
      ) values (
        v_order_id, v_line_number, v_product_id, v_variant_id, v_qty,
        v_product.name_en, (to_jsonb(v_product)->>'selected_size_label'), v_base_price,
        0, 0, v_base_price * v_qty, nullif(btrim(v_item->>'notes'),''),
        jsonb_build_object(
          'product_id', v_product_id, 'variant_id', v_variant_id,
          'product_legacy_id', v_product.legacy_id,
          'variant_legacy_id', (select legacy_id from public.product_variants where id = v_variant_id),
          'size_key', (to_jsonb(v_product)->>'selected_size_key'),
          'base_unit_price', v_base_price
        )
      ) returning id into v_item_id;

      v_modifier_total := 0;
      for v_modifier in select value from jsonb_array_elements(v_modifiers)
      loop
        v_group_id := nullif(v_modifier->>'group_id','')::uuid;
        v_modifier_id := nullif(v_modifier->>'modifier_id','')::uuid;
        if v_group_id is null or v_modifier_id is null then
          raise exception using errcode = '22023', message = 'MODIFIER_SELECTION_INVALID: Each modifier needs a group_id and modifier_id.';
        end if;

        select mg.name_en as group_name, mg.id as group_id, m.name_en as modifier_name,
               m.legacy_id as modifier_legacy_id, m.price_mode, m.fixed_price,
               mg.max_select
        into v_mod
        from public.modifier_groups mg
        join public.modifiers m on m.modifier_group_id = mg.id
        join public.modifier_group_assignments a on a.modifier_group_id = mg.id and a.product_id = v_product_id
        where mg.id = v_group_id and m.id = v_modifier_id
          and mg.is_active = true and m.is_active = true and a.is_active = true;

        if not found then
          raise exception using errcode = '22023', message = 'MODIFIER_NOT_ALLOWED: A selected extra is not assigned to this product.';
        end if;

        case upper(v_mod.price_mode)
          when 'FREE' then v_modifier_price := 0;
          when 'FIXED' then v_modifier_price := coalesce(v_mod.fixed_price, 0);
          when 'BY_SIZE' then
            select mpr.price into v_modifier_price
            from public.modifier_price_rules mpr
            where mpr.modifier_id = v_modifier_id
              and mpr.size_key = (to_jsonb(v_product)->>'selected_size_key');
            if not found then
              raise exception using errcode = '22023', message = 'MODIFIER_PRICE_MISSING: No size-specific price exists for a selected extra.';
            end if;
          else
            raise exception using errcode = '22023', message = 'MODIFIER_PRICE_MODE_INVALID: A selected extra has an unsupported pricing mode.';
        end case;

        insert into public.order_item_modifiers (
          order_item_id, order_item_component_id, modifier_group_id, modifier_id,
          quantity, modifier_group_name_snapshot, modifier_name_snapshot,
          unit_price_snapshot, total_price_snapshot, modifier_snapshot
        ) values (
          v_item_id, null, v_group_id, v_modifier_id,
          v_qty, v_mod.group_name, v_mod.modifier_name,
          v_modifier_price, v_modifier_price * v_qty,
          jsonb_build_object(
            'modifier_legacy_id', v_mod.modifier_legacy_id,
            'price_mode', v_mod.price_mode,
            'size_key', (to_jsonb(v_product)->>'selected_size_key'),
            'unit_price', v_modifier_price
          )
        );
        v_modifier_total := v_modifier_total + v_modifier_price;
      end loop;

      v_line_total := (v_base_price + v_modifier_total) * v_qty;
      update public.order_items
      set line_total = v_line_total,
          item_snapshot = item_snapshot || jsonb_build_object('modifier_total_per_unit', v_modifier_total)
      where id = v_item_id;
      v_subtotal := v_subtotal + v_line_total;

    elsif v_line_kind = 'deal' then
      v_deal_id := nullif(v_item->>'deal_id','')::uuid;
      select * into v_deal
      from public.deals d
      where d.id = v_deal_id
        and d.restaurant_id = v_restaurant_id
        and d.is_active = true and d.is_available = true;

      if not found then
        raise exception using errcode = '22023', message = 'DEAL_UNAVAILABLE: One of the selected deals is no longer available.';
      end if;

      v_base_price := v_deal.bundle_price;
      v_line_total := v_base_price * v_qty;

      insert into public.order_items (
        order_id, line_number, deal_id, quantity, deal_title_snapshot,
        unit_price_snapshot, discount_amount, tax_amount, line_total, item_snapshot
      ) values (
        v_order_id, v_line_number, v_deal_id, v_qty, v_deal.title,
        v_base_price, 0, 0, v_line_total,
        jsonb_build_object('deal_id', v_deal_id, 'deal_legacy_id', v_deal.legacy_id, 'bundle_price', v_base_price)
      ) returning id into v_item_id;

      v_choices := coalesce(v_item->'choices','{}'::jsonb);
      if jsonb_typeof(v_choices) <> 'object' then
        raise exception using errcode = '22023', message = 'DEAL_CHOICES_INVALID: Deal choices must be an object keyed by deal component ID.';
      end if;

      for v_component in
        select dc.*
        from public.deal_components dc
        where dc.deal_id = v_deal_id
        order by dc.sort_order, dc.id
      loop
        v_selected_product_id := null;
        v_selected_variant_id := null;
        v_selected_product_name := null;
        v_selected_variant_label := null;
        v_component_name := coalesce(nullif(v_component.description_phrase,''), nullif(v_component.display_name,''));
        v_component_volume := v_component.volume_key;
        v_component_qty := v_component.quantity * v_qty;

        if v_component.ref_type = 'FIXED_PRODUCT' then
          select p.id, p.name_en, vx.id, vx.size_label
          into v_selected_product_id, v_selected_product_name, v_selected_variant_id, v_selected_variant_label
          from public.products p
          left join lateral (
            select vv.id, vv.size_label
            from public.product_variants vv
            where vv.product_id = p.id and vv.is_active = true and vv.is_available = true
            order by vv.sort_order, vv.id
            limit 1
          ) vx on true
          where p.id = v_component.product_id
            and p.is_active = true and p.is_available = true;

          if not found then
            raise exception using errcode = '22023', message = 'DEAL_COMPONENT_UNAVAILABLE: A fixed product in this deal is no longer available.';
          end if;
          v_component_name := coalesce(v_selected_product_name, v_component_name);

        elsif v_component.ref_type = 'FIXED_VARIANT' then
          select p.id, p.name_en, vv.id, vv.size_label
          into v_selected_product_id, v_selected_product_name, v_selected_variant_id, v_selected_variant_label
          from public.product_variants vv
          join public.products p on p.id = vv.product_id
          where vv.id = v_component.product_variant_id
            and vv.is_active = true and vv.is_available = true
            and p.is_active = true and p.is_available = true;

          if not found then
            raise exception using errcode = '22023', message = 'DEAL_COMPONENT_UNAVAILABLE: A fixed variant in this deal is no longer available.';
          end if;
          v_component_name := coalesce(v_selected_product_name, v_component_name);

        elsif v_component.ref_type = 'CHOICE_BY_SIZE' then
          v_variant_id := nullif(v_choices->>v_component.id::text,'')::uuid;
          if v_variant_id is null then
            raise exception using errcode = '22023', message = 'DEAL_CHOICE_REQUIRED: Complete all required product selections for the selected deal.';
          end if;

          select p.id, p.name_en, vv.id, vv.size_label
          into v_selected_product_id, v_selected_product_name, v_selected_variant_id, v_selected_variant_label
          from public.product_variants vv
          join public.products p on p.id = vv.product_id
          where vv.id = v_variant_id
            and vv.size_key = v_component.size_key
            and p.subcategory_id = v_component.pool_subcategory_id
            and vv.is_active = true and vv.is_available = true
            and p.is_active = true and p.is_available = true;

          if not found then
            raise exception using errcode = '22023', message = 'DEAL_CHOICE_INVALID: A selected deal product does not match the required category and size.';
          end if;
          v_component_name := coalesce(v_selected_product_name, v_component_name);

        elsif v_component.ref_type = 'DRINK_INCLUDED' then
          -- Current HFP deal definitions include a drink volume as a fixed bundle component.
          -- There are no DrinkOptions rows yet, and the website does not ask customers to choose a drink flavour.
          v_component_name := coalesce(v_component_name, 'Included drink');

        else
          raise exception using errcode = '22023', message = 'DEAL_COMPONENT_UNSUPPORTED: This deal contains an unsupported component type.';
        end if;

        v_component_snapshot := jsonb_build_object(
          'deal_component_id', v_component.id,
          'legacy_id', v_component.legacy_id,
          'ref_type', v_component.ref_type,
          'description_phrase', v_component.description_phrase,
          'volume_key', v_component.volume_key
        );

        insert into public.order_item_components (
          order_item_id, deal_component_id, component_type,
          selected_product_id, selected_variant_id, selected_drink_option_id,
          quantity, name_snapshot, variant_snapshot, volume_snapshot,
          unit_price_snapshot, component_snapshot
        ) values (
          v_item_id, v_component.id, v_component.component_type,
          v_selected_product_id, v_selected_variant_id, null,
          v_component_qty, coalesce(v_component_name, v_component.component_type),
          v_selected_variant_label, v_component_volume,
          0, v_component_snapshot
        );
      end loop;

      v_subtotal := v_subtotal + v_line_total;
    else
      raise exception using errcode = '22023', message = 'ORDER_LINE_KIND_INVALID: Each order line must be product or deal.';
    end if;
  end loop;

  update public.orders
  set subtotal = v_subtotal,
      delivery_fee = v_delivery_fee,
      delivery_area_fee_snapshot = v_delivery_fee,
      total = v_subtotal + v_delivery_fee,
      balance_due = v_subtotal + v_delivery_fee,
      address_snapshot = jsonb_build_object(
        'address', v_address,
        'area_id', v_delivery_area_id,
        'area_name', v_delivery_area_name,
        'delivery_fee', v_delivery_fee,
        'instructions', v_delivery_instructions,
        'table_number', v_table_number
      )
  where id = v_order_id
  returning * into v_order;

  return jsonb_build_object(
    'ok', true,
    'idempotent_replay', false,
    'order', jsonb_build_object(
      'id', v_order.id,
      'order_number', v_order.order_number,
      'status', v_order.status,
      'source', v_order.source,
      'fulfillment_type', v_order.fulfillment_type,
      'subtotal', v_order.subtotal,
      'delivery_fee', v_order.delivery_fee,
      'total', v_order.total,
      'currency_code', v_order.currency_code,
      'payment_status', v_order.payment_status,
      'created_at', v_order.created_at
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.hfp_decline_delivery_offer(p_offer_id uuid, p_rider_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_task_id uuid;
  v_task public.delivery_tasks%rowtype;
  v_offer public.delivery_task_offers%rowtype;
  v_now timestamptz := pg_catalog.now();
begin
  select dto.delivery_task_id into v_task_id
  from public.delivery_task_offers dto
  where dto.id = p_offer_id and dto.rider_user_id = p_rider_user_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'OFFER_NOT_FOUND: This delivery offer is no longer available.';
  end if;

  select * into v_task from public.delivery_tasks dt where dt.id = v_task_id for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'DELIVERY_TASK_NOT_FOUND: This delivery no longer exists.';
  end if;

  select * into v_offer
  from public.delivery_task_offers dto
  where dto.id = p_offer_id and dto.delivery_task_id = v_task_id and dto.rider_user_id = p_rider_user_id
  for update;
  if not found or v_offer.status <> 'offered' or v_offer.expires_at <= v_now then
    raise exception using errcode = '22023', message = 'OFFER_EXPIRED_OR_TAKEN: This offer has expired or is no longer available.';
  end if;

  update public.delivery_task_offers
  set status = 'rejected',
      responded_at = v_now,
      response_reason = left(coalesce(nullif(pg_catalog.btrim(p_reason),''),'Rider declined'), 240)
  where id = p_offer_id;

  return jsonb_build_object('ok',true,'offer_id',p_offer_id,'status','rejected');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.hfp_get_rider_push_config()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'vapid_keys', ds.decrypted_secret::jsonb,
    'vapid_public_key', c.vapid_public_key,
    'contact_information', c.contact_information
  )
  from private.rider_push_config c
  join vault.decrypted_secrets ds on ds.id = c.vapid_secret_id
  where c.singleton = true;
$function$
;

CREATE OR REPLACE FUNCTION public.hfp_manage_delivery(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_action text;
  v_task_id uuid;
  v_actor_user_id uuid;
  v_rider_user_id uuid;
  v_reason text;
  v_actor_role text;
  v_task public.delivery_tasks%rowtype;
  v_order public.orders%rowtype;
  v_assignment public.delivery_assignments%rowtype;
  v_is_valid_rider boolean := false;
  v_now timestamptz := pg_catalog.now();
  v_event_type text;
  v_rider_profile public.rider_profiles%rowtype;
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception using errcode = '22023', message = 'DELIVERY_REQUEST_INVALID: A JSON object is required.';
  end if;

  v_action := pg_catalog.lower(coalesce(p_payload->>'action',''));
  v_task_id := nullif(p_payload->>'delivery_task_id','')::uuid;
  v_actor_user_id := nullif(p_payload->>'actor_user_id','')::uuid;
  v_reason := nullif(pg_catalog.btrim(p_payload->>'reason'),'');
  if v_task_id is null or v_actor_user_id is null or v_action = '' then
    raise exception using errcode = '22023', message = 'DELIVERY_REQUEST_INVALID: action, delivery_task_id and authenticated actor are required.';
  end if;

  select * into v_task from public.delivery_tasks dt where dt.id = v_task_id for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'DELIVERY_TASK_NOT_FOUND: Delivery task was not found.';
  end if;

  select * into v_order from public.orders o where o.id = v_task.order_id for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'ORDER_NOT_FOUND: The delivery task has no matching order.';
  end if;
  if v_order.fulfillment_type <> 'delivery' then
    raise exception using errcode = '22023', message = 'DELIVERY_FULFILLMENT_REQUIRED: Rider actions are only valid for delivery orders.';
  end if;
  v_now := pg_catalog.clock_timestamp();

  if v_action = 'assign' then
    v_rider_user_id := nullif(p_payload->>'rider_user_id','')::uuid;
    if v_rider_user_id is null then
      raise exception using errcode = '22023', message = 'RIDER_REQUIRED: Choose an HFP rider to assign.';
    end if;

    select ur.role into v_actor_role
    from public.user_roles ur
    where ur.user_id = v_actor_user_id and ur.is_active = true
      and (ur.branch_id is null or ur.branch_id = v_task.branch_id)
      and ur.role in ('owner','admin','manager','cashier')
    order by case ur.role when 'owner' then 1 when 'admin' then 2 when 'manager' then 3 else 4 end
    limit 1;
    if v_actor_role is null then
      raise exception using errcode = '42501', message = 'DISPATCH_ROLE_REQUIRED: Only authorized HFP staff can assign riders.';
    end if;

    select * into v_assignment
    from public.delivery_assignments da
    where da.delivery_task_id = v_task_id and da.is_current = true
    order by da.assigned_at desc limit 1 for update;
    if found then
      if v_assignment.rider_user_id = v_rider_user_id then
        return jsonb_build_object('ok',true,'unchanged',true,'delivery_task_id',v_task_id,'assignment_id',v_assignment.id,'task_status',v_task.status,'assignment_status',v_assignment.status);
      end if;
      raise exception using errcode = '23505', message = 'DELIVERY_ALREADY_ASSIGNED: End the current assignment before assigning another rider.';
    end if;

    if v_order.status <> 'ready' then
      raise exception using errcode = '22023', message = 'ORDER_NOT_READY: A delivery can only be assigned after the order is ready.';
    end if;
    if v_task.status not in ('dispatch_pending','offering') then
      raise exception using errcode = '22023', message = 'DELIVERY_TASK_NOT_ASSIGNABLE: This delivery task is not awaiting assignment.';
    end if;

    select * into v_rider_profile
    from public.rider_profiles rp
    where rp.user_id = v_rider_user_id and rp.branch_id = v_task.branch_id
    for update;
    if not found then
      raise exception using errcode = '42501', message = 'RIDER_NOT_AVAILABLE: The selected user is not an active, available HFP rider for this branch.';
    end if;
    v_now := pg_catalog.clock_timestamp();

    if exists (
      select 1 from public.delivery_assignments active_da
      where active_da.rider_user_id = v_rider_user_id
        and active_da.is_current = true
        and active_da.status in ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery','failed')
    ) then
      raise exception using errcode = '42501', message = 'RIDER_ALREADY_BUSY: This rider already has an active delivery.';
    end if;

    select exists (
      select 1 from public.rider_profiles rp
      join public.user_roles ur on ur.user_id = rp.user_id
        and ur.is_active = true and ur.role = 'rider'
        and (ur.branch_id is null or ur.branch_id = rp.branch_id)
      where rp.user_id = v_rider_user_id and rp.branch_id = v_task.branch_id
        and rp.is_active = true and rp.availability_status = 'available'
        and rp.accepting_jobs = true
        and rp.last_seen_at >= v_now - interval '4 minutes'
        and not exists (
          select 1
          from public.delivery_tasks unresolved
          join public.delivery_assignments unresolved_assignment
            on unresolved_assignment.delivery_task_id = unresolved.id
          where unresolved.branch_id = v_task.branch_id
            and unresolved.status = 'failed'
            and unresolved.return_confirmed_at is null
            and unresolved_assignment.rider_user_id = rp.user_id
        )
    ) into v_is_valid_rider;
    if not v_is_valid_rider then
      raise exception using errcode = '42501', message = 'RIDER_NOT_AVAILABLE: The selected user is not an active, available HFP rider for this branch.';
    end if;

    insert into public.delivery_assignments(delivery_task_id,rider_user_id,status,is_current,assigned_at)
    values(v_task_id,v_rider_user_id,'assigned',true,v_now)
    returning * into v_assignment;

    update public.rider_profiles set availability_status='busy',updated_at=v_now
    where user_id=v_rider_user_id and branch_id=v_task.branch_id;
    update public.delivery_tasks set status='assigned',assigned_at=v_now,failed_at=null,failure_reason=null where id=v_task_id;

    insert into public.order_events(order_id,event_type,actor_user_id,actor_type,payload)
    values(v_order.id,'delivery.assigned',v_actor_user_id,
      case when v_actor_role in ('owner','admin') then 'admin' else 'staff' end,
      jsonb_build_object('delivery_task_id',v_task_id,'assignment_id',v_assignment.id,'rider_user_id',v_rider_user_id));

    return jsonb_build_object('ok',true,'unchanged',false,'delivery_task_id',v_task_id,'assignment_id',v_assignment.id,'rider_user_id',v_rider_user_id,'task_status','assigned','assignment_status','assigned');
  end if;

  if v_action='confirm_return' then
    select ur.role into v_actor_role
    from public.user_roles ur
    where ur.user_id=v_actor_user_id and ur.is_active=true
      and ur.role in ('owner','admin','manager')
      and (ur.branch_id is null or ur.branch_id=v_task.branch_id)
    order by case ur.role when 'owner' then 1 when 'admin' then 2 else 3 end
    limit 1;
    if v_actor_role is null then
      raise exception using errcode = '42501', message = 'RETURN_CONFIRM_ROLE_REQUIRED: Only an HFP owner, admin or manager can confirm the returned order.';
    end if;
    if v_task.status <> 'failed' then
      raise exception using errcode = '22023', message = 'DELIVERY_NOT_FAILED: Only a delivery with a reported issue can be returned.';
    end if;
    if v_task.return_confirmed_at is not null then
      return jsonb_build_object('ok',true,'unchanged',true,'delivery_task_id',v_task_id,'task_status',v_task.status,'return_confirmed_at',v_task.return_confirmed_at);
    end if;
    if v_task.return_reported_at is null then
      raise exception using errcode = '22023', message = 'RIDER_RETURN_NOT_REPORTED: The rider must first report that the order has been returned to the restaurant.';
    end if;

    select * into v_assignment
    from public.delivery_assignments da
    where da.delivery_task_id=v_task_id
    order by da.is_current desc, da.assigned_at desc
    limit 1 for update;
    if not found or v_assignment.status not in ('picked_up','out_for_delivery','failed') then
      raise exception using errcode = '22023', message = 'RETURN_ASSIGNMENT_INVALID: The latest rider assignment cannot be closed as a returned delivery.';
    end if;

    -- Record physical handover. This is the manager's single final action.
    update public.delivery_tasks
    set return_confirmed_at=v_now, return_confirmed_by=v_actor_user_id
    where id=v_task_id;

    -- Cancel the order atomically with return confirmation. The orders status
    -- trigger writes the normal status history, audit event and outbox record.
    -- Payment rows and inventory are deliberately not changed here.
    v_reason := 'Delivery returned to restaurant after failed delivery: ' ||
      coalesce(v_task.failure_reason,'Delivery issue reported');

    update public.orders
    set status='cancelled',
        cancelled_at=coalesce(cancelled_at,v_now),
        cancelled_by_type='staff',
        cancelled_by_user_id=v_actor_user_id,
        cancellation_reason=v_reason,
        last_status_changed_by=v_actor_user_id,
        last_status_actor_type='staff',
        last_status_change_reason=v_reason
    where id=v_order.id and status='out_for_delivery';
    if not found then
      raise exception using errcode = '22023',
        message = 'RETURN_ORDER_STATUS_INVALID: Only an out-for-delivery order can be cancelled after return confirmation.';
    end if;

    update public.delivery_tasks
    set status='cancelled'
    where id=v_task_id and status='failed' and return_confirmed_at is not null;

    update public.delivery_assignments
    set status='failed',is_current=false,ended_at=coalesce(ended_at,v_now),
        end_reason=coalesce(end_reason,v_task.failure_reason,'Delivery issue reported')
    where id=v_assignment.id;

    update public.rider_profiles
    set availability_status=case when accepting_jobs = true and last_seen_at >= v_now - interval '4 minutes' then 'available' else 'offline' end,updated_at=v_now
    where user_id=v_assignment.rider_user_id and branch_id=v_task.branch_id
      and is_active=true and availability_status<>'suspended'
      and not exists (
        select 1 from public.delivery_assignments active_assignment
        where active_assignment.rider_user_id=v_assignment.rider_user_id
          and active_assignment.is_current=true
          and active_assignment.status in ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery')
      );

    insert into public.order_events(order_id,event_type,actor_user_id,actor_type,payload)
    values(v_order.id,'delivery.return_confirmed',v_actor_user_id,
      case when v_actor_role in ('owner','admin') then 'admin' else 'staff' end,
      jsonb_build_object('delivery_task_id',v_task_id,'assignment_id',v_assignment.id,
        'rider_user_id',v_assignment.rider_user_id,'failure_reason',v_task.failure_reason,
        'order_status','cancelled'));

    return jsonb_build_object('ok',true,'unchanged',false,'delivery_task_id',v_task_id,
      'order_id',v_order.id,'order_number',v_order.order_number,'task_status','cancelled',
      'order_status','cancelled','assignment_status','failed','return_confirmed_at',v_now);
  end if;

  select ur.role into v_actor_role
  from public.user_roles ur
  where ur.user_id=v_actor_user_id and ur.is_active=true and ur.role='rider'
    and (ur.branch_id is null or ur.branch_id=v_task.branch_id)
  limit 1;
  if v_actor_role is null or not exists (
    select 1 from public.rider_profiles rp
    where rp.user_id=v_actor_user_id and rp.branch_id=v_task.branch_id
      and rp.is_active=true and rp.availability_status <> 'suspended'
  ) then
    raise exception using errcode = '42501', message = 'RIDER_ROLE_REQUIRED: This account is not an active HFP rider for this branch.';
  end if;

  select * into v_assignment
  from public.delivery_assignments da
  where da.delivery_task_id=v_task_id and da.rider_user_id=v_actor_user_id
  order by da.assigned_at desc limit 1 for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'RIDER_ASSIGNMENT_NOT_FOUND: This delivery is not assigned to this rider.';
  end if;

  if v_action='accept' then
    if v_assignment.status in ('accepted','arrived_at_restaurant','picked_up','out_for_delivery','delivered') then
      return jsonb_build_object('ok',true,'unchanged',true,'delivery_task_id',v_task_id,'assignment_id',v_assignment.id,'task_status',v_task.status,'assignment_status',v_assignment.status);
    end if;
    if not v_assignment.is_current or v_assignment.status<>'assigned' or v_task.status<>'assigned' then
      raise exception using errcode = '22023', message = 'DELIVERY_ACTION_NOT_ALLOWED: Only a currently assigned rider can accept this delivery.';
    end if;
    update public.delivery_assignments set status='accepted',accepted_at=coalesce(accepted_at,v_now) where id=v_assignment.id;
    update public.delivery_tasks set status='accepted' where id=v_task_id;
    v_event_type:='delivery.rider_accepted';

  elsif v_action='arrive' then
    if v_assignment.status in ('arrived_at_restaurant','picked_up','out_for_delivery','delivered') then
      return jsonb_build_object('ok',true,'unchanged',true,'delivery_task_id',v_task_id,'assignment_id',v_assignment.id,'task_status',v_task.status,'assignment_status',v_assignment.status);
    end if;
    if not v_assignment.is_current or v_assignment.status<>'accepted' or v_task.status<>'accepted' then
      raise exception using errcode = '22023', message = 'DELIVERY_ACTION_NOT_ALLOWED: Accept the delivery before marking arrival.';
    end if;
    update public.delivery_assignments set status='arrived_at_restaurant',arrived_at=coalesce(arrived_at,v_now) where id=v_assignment.id;
    update public.delivery_tasks set status='arrived_at_restaurant' where id=v_task_id;
    v_event_type:='delivery.rider_arrived';

  elsif v_action='picked_up' then
    if v_assignment.status in ('picked_up','out_for_delivery','delivered') then
      return jsonb_build_object('ok',true,'unchanged',true,'delivery_task_id',v_task_id,'assignment_id',v_assignment.id,'task_status',v_task.status,'assignment_status',v_assignment.status);
    end if;
    if not v_assignment.is_current or v_assignment.status not in ('accepted','arrived_at_restaurant')
       or v_task.status not in ('accepted','arrived_at_restaurant') or v_order.status<>'ready' then
      raise exception using errcode = '22023', message = 'DELIVERY_ACTION_NOT_ALLOWED: The rider must accept the ready delivery before pickup.';
    end if;
    update public.delivery_assignments set status='picked_up',picked_up_at=coalesce(picked_up_at,v_now) where id=v_assignment.id;
    update public.delivery_tasks set status='out_for_delivery',picked_up_at=coalesce(picked_up_at,v_now),out_for_delivery_at=coalesce(out_for_delivery_at,v_now) where id=v_task_id;
    v_event_type:='delivery.rider_picked_up';

  elsif v_action='delivered' then
    if v_assignment.status='delivered' then
      return jsonb_build_object('ok',true,'unchanged',true,'delivery_task_id',v_task_id,'assignment_id',v_assignment.id,'task_status',v_task.status,'assignment_status',v_assignment.status);
    end if;
    if not v_assignment.is_current or v_assignment.status not in ('picked_up','out_for_delivery')
       or v_task.status not in ('picked_up','out_for_delivery') or v_order.status<>'out_for_delivery' then
      raise exception using errcode = '22023', message = 'DELIVERY_ACTION_NOT_ALLOWED: Only a picked-up delivery can be marked delivered.';
    end if;
    update public.delivery_tasks set status='delivered',delivered_at=coalesce(delivered_at,v_now) where id=v_task_id;
    update public.delivery_assignments set status='delivered',is_current=false,delivered_at=coalesce(delivered_at,v_now),ended_at=coalesce(ended_at,v_now) where id=v_assignment.id;
    update public.rider_profiles set availability_status=case when accepting_jobs = true and last_seen_at >= v_now - interval '4 minutes' then 'available' else 'offline' end,updated_at=v_now
    where user_id=v_actor_user_id and branch_id=v_task.branch_id and is_active=true and availability_status<>'suspended';
    v_event_type:='delivery.rider_delivered';

  elsif v_action='reject' then
    if v_assignment.status='reassigned' and not v_assignment.is_current then
      return jsonb_build_object('ok',true,'unchanged',true,'delivery_task_id',v_task_id,'assignment_id',v_assignment.id,'task_status',v_task.status,'assignment_status',v_assignment.status);
    end if;
    if v_reason is null then
      raise exception using errcode = '22023', message = 'DELIVERY_REASON_REQUIRED: A reason is required when rejecting an assignment.';
    end if;
    if not v_assignment.is_current or v_assignment.status not in ('assigned','accepted','arrived_at_restaurant') then
      raise exception using errcode = '22023', message = 'DELIVERY_ACTION_NOT_ALLOWED: This assignment can no longer be rejected.';
    end if;
    update public.delivery_assignments set status='reassigned',is_current=false,ended_at=v_now,end_reason=v_reason where id=v_assignment.id;
    update public.delivery_tasks set status='dispatch_pending',assigned_at=null where id=v_task_id;
    update public.rider_profiles set availability_status=case when accepting_jobs = true and last_seen_at >= v_now - interval '4 minutes' then 'available' else 'offline' end,updated_at=v_now
    where user_id=v_actor_user_id and branch_id=v_task.branch_id and is_active=true and availability_status<>'suspended';
    v_event_type:='delivery.rider_rejected';

  elsif v_action='failed' then
    if v_task.status='failed' then
      return jsonb_build_object('ok',true,'unchanged',true,'delivery_task_id',v_task_id,
        'assignment_id',v_assignment.id,'task_status',v_task.status,'assignment_status',v_assignment.status,
        'return_reported_at',v_task.return_reported_at);
    end if;
    if not v_assignment.is_current or v_assignment.status not in ('picked_up','out_for_delivery')
       or v_task.status not in ('picked_up','out_for_delivery') then
      raise exception using errcode = '22023', message = 'DELIVERY_ACTION_NOT_ALLOWED: Only a currently active, picked-up delivery can be reported failed.';
    end if;
    if v_reason is null then
      raise exception using errcode = '22023', message = 'DELIVERY_REASON_REQUIRED: A reason is required when reporting a failed delivery.';
    end if;

    -- Keep the rider assignment current and the rider busy until the physical return is confirmed.
    update public.delivery_tasks
    set status='failed',failed_at=coalesce(failed_at,v_now),failure_reason=v_reason,
        return_reported_at=null,return_reported_by=null,return_confirmed_at=null,return_confirmed_by=null
    where id=v_task_id;
    update public.delivery_assignments
    set status='failed',end_reason=v_reason
    where id=v_assignment.id;
    v_event_type:='delivery.rider_failed';

  elsif v_action='return_reported' then
    if v_task.return_confirmed_at is not null then
      return jsonb_build_object('ok',true,'unchanged',true,'delivery_task_id',v_task_id,
        'task_status',v_task.status,'return_confirmed_at',v_task.return_confirmed_at);
    end if;
    if v_task.status<>'failed' or v_assignment.status not in ('picked_up','out_for_delivery','failed') then
      raise exception using errcode = '22023', message = 'DELIVERY_RETURN_REPORT_NOT_ALLOWED: Report the delivery issue first and keep the same rider assignment.';
    end if;
    if v_task.return_reported_at is not null then
      return jsonb_build_object('ok',true,'unchanged',true,'delivery_task_id',v_task_id,
        'assignment_id',v_assignment.id,'task_status',v_task.status,'return_reported_at',v_task.return_reported_at);
    end if;
    update public.delivery_tasks
    set return_reported_at=v_now,return_reported_by=v_actor_user_id
    where id=v_task_id;
    -- Legacy failed assignments may have released the rider before this workflow was deployed.
    -- Restore busy state while the manager verifies the physical return.
    update public.rider_profiles
    set availability_status='busy',updated_at=v_now
    where user_id=v_actor_user_id and branch_id=v_task.branch_id
      and is_active=true and availability_status<>'suspended';
    v_event_type:='delivery.rider_return_reported';

  else
    raise exception using errcode = '22023', message = 'DELIVERY_ACTION_INVALID: Supported actions are assign, accept, arrive, picked_up, delivered, reject, failed, return_reported and confirm_return.';
  end if;

  insert into public.order_events(order_id,event_type,actor_user_id,actor_type,payload)
  values(v_order.id,v_event_type,v_actor_user_id,'rider',
    jsonb_build_object('delivery_task_id',v_task_id,'assignment_id',v_assignment.id,'delivery_action',v_action,'reason',v_reason));

  return jsonb_build_object(
    'ok',true,'unchanged',false,'delivery_task_id',v_task_id,'order_id',v_order.id,
    'order_number',v_order.order_number,'assignment_id',v_assignment.id,
    'task_status',(select dt.status from public.delivery_tasks dt where dt.id=v_task_id),
    'assignment_status',(select da.status from public.delivery_assignments da where da.id=v_assignment.id)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.hfp_manage_staff_role(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_restaurant_id uuid;
  v_actor uuid;
  v_target uuid;
  v_branch uuid;
  v_role_id uuid;
  v_role text;
  v_action text;
  v_active boolean;
  v_name text;
  v_phone text;
  v_old_role text;
  v_old_active boolean;
  v_previous_role text;
  v_previous_active boolean;
  v_existing_id uuid;
  v_now timestamptz := now();
  v_audit_action text;
  v_current_rider boolean := false;
  v_active_owner_count integer := 0;
begin
  if jsonb_typeof(p_payload) <> 'object' then
    raise exception 'INVALID_REQUEST: payload must be an object';
  end if;

  select r.id into v_restaurant_id
  from public.restaurants r
  where r.slug = 'flame-chick' and r.is_active
  limit 1;
  if v_restaurant_id is null then
    raise exception 'TENANT_NOT_FOUND: Flame Chick tenant is not active';
  end if;

  begin v_actor := (p_payload->>'actor_user_id')::uuid;
  exception when others then raise exception 'ACTOR_REQUIRED: actor_user_id must be a UUID'; end;
  begin v_target := (p_payload->>'target_user_id')::uuid;
  exception when others then raise exception 'TARGET_REQUIRED: target_user_id must be a UUID'; end;
  begin v_branch := (p_payload->>'branch_id')::uuid;
  exception when others then raise exception 'BRANCH_REQUIRED: branch_id must be a UUID'; end;

  v_action := lower(coalesce(p_payload->>'action',''));
  if v_action not in ('assign','set_active') then
    raise exception 'ACTION_INVALID: unsupported staff role action';
  end if;

  if not exists (select 1 from auth.users u where u.id = v_target) then
    raise exception 'AUTH_USER_NOT_FOUND: target Auth user does not exist';
  end if;

  if not exists (
    select 1 from public.branches b
    where b.id = v_branch and b.restaurant_id = v_restaurant_id and b.is_active
  ) then
    raise exception 'BRANCH_INVALID: branch is not an active Flame Chick branch';
  end if;

  if not exists (
    select 1 from public.user_roles ur
    where ur.user_id = v_actor and ur.is_active and ur.role = 'owner'
      and (ur.branch_id is null or ur.branch_id = v_branch)
  ) then
    raise exception 'OWNER_REQUIRED: only an active Flame Chick owner can change team roles';
  end if;

  if v_action = 'assign' then
    v_role := lower(coalesce(p_payload->>'role',''));
    if v_role not in ('owner','admin','manager','cashier','kitchen','rider') then
      raise exception 'ROLE_INVALID: choose a supported Flame Chick role';
    end if;

    v_name := nullif(btrim(coalesce(p_payload->>'full_name','')), '');
    v_phone := nullif(btrim(coalesce(p_payload->>'phone','')), '');

    select ur.role, ur.is_active
      into v_previous_role, v_previous_active
    from public.user_roles ur
    where ur.user_id = v_target and ur.branch_id = v_branch and ur.is_active
    order by case ur.role when 'owner' then 1 when 'admin' then 2 when 'manager' then 3 when 'cashier' then 4 when 'kitchen' then 5 else 6 end
    limit 1;

    select ur.id, ur.role, ur.is_active
      into v_existing_id, v_old_role, v_old_active
    from public.user_roles ur
    where ur.user_id = v_target and ur.branch_id = v_branch and ur.role = v_role
    limit 1;

    select exists (
      select 1 from public.user_roles ur
      where ur.user_id = v_target and ur.branch_id = v_branch
        and ur.role = 'rider' and ur.is_active
    ) into v_current_rider;

    if v_current_rider and v_role <> 'rider' then
      if exists (
        select 1
        from public.delivery_assignments da
        join public.delivery_tasks dt on dt.id = da.delivery_task_id
        where da.rider_user_id = v_target
          and da.is_current
          and dt.status in ('assigned','accepted','arrived_at_restaurant','out_for_delivery','picked_up','failed')
      ) then
        raise exception 'RIDER_HAS_ACTIVE_DELIVERIES: finish or reassign this rider active delivery before changing role';
      end if;
    end if;

    if v_previous_role = 'owner' and v_role <> 'owner' then
      select count(*) into v_active_owner_count
      from public.user_roles ur
      left join public.branches b on b.id = ur.branch_id
      where ur.role = 'owner' and ur.is_active
        and (ur.branch_id is null or b.restaurant_id = v_restaurant_id);
      if v_active_owner_count <= 1 then
        raise exception 'LAST_OWNER_PROTECTED: cannot remove the last active owner';
      end if;
    end if;

    if v_existing_id is not null then
      update public.user_roles
      set is_active = false
      where user_id = v_target and branch_id = v_branch and role <> v_role and is_active;
      update public.user_roles
      set is_active = true, created_by = coalesce(created_by, v_actor)
      where id = v_existing_id;
    else
      update public.user_roles
      set is_active = false
      where user_id = v_target and branch_id = v_branch and is_active;

      insert into public.user_roles(user_id, branch_id, role, is_active, created_by)
      values (v_target, v_branch, v_role, true, v_actor)
      returning id into v_existing_id;
    end if;

    insert into public.user_profiles(id, full_name, phone, is_active, updated_at)
    values (v_target, v_name, v_phone, true, v_now)
    on conflict (id) do update
      set full_name = coalesce(excluded.full_name, public.user_profiles.full_name),
          phone = coalesce(excluded.phone, public.user_profiles.phone),
          is_active = true,
          updated_at = v_now;

    if v_role = 'rider' then
      insert into public.rider_profiles(
        user_id, branch_id, rider_code, display_name, phone,
        availability_status, is_active, updated_at
      )
      values (
        v_target, v_branch,
        'PB-R-' || upper(substr(replace(v_target::text,'-',''),1,8)),
        coalesce(v_name, 'Flame Chick Rider'), v_phone,
        'offline', true, v_now
      )
      on conflict (user_id) do update
        set branch_id = excluded.branch_id,
            display_name = coalesce(excluded.display_name, public.rider_profiles.display_name),
            phone = coalesce(excluded.phone, public.rider_profiles.phone),
            availability_status = case
              when public.rider_profiles.is_active then public.rider_profiles.availability_status
              else 'offline'
            end,
            is_active = true,
            updated_at = v_now;
    else
      update public.rider_profiles
      set is_active = false, availability_status = 'offline', updated_at = v_now
      where user_id = v_target;
    end if;

    if coalesce((p_payload->>'invitation_sent')::boolean,false) then
      v_audit_action := 'member_invited';
    elsif v_previous_role is null then
      v_audit_action := case when v_old_active is false then 'role_reactivated' else 'existing_member_attached' end;
    elsif v_previous_role <> v_role then
      v_audit_action := 'role_changed';
    elsif v_old_active is false then
      v_audit_action := 'role_reactivated';
    else
      v_audit_action := 'existing_member_attached';
    end if;

    insert into public.staff_role_audit(
      restaurant_id, branch_id, actor_user_id, target_user_id, action,
      old_role, new_role, old_is_active, new_is_active, details
    )
    values (
      v_restaurant_id, v_branch, v_actor, v_target, v_audit_action,
      v_previous_role, v_role, v_previous_active, true,
      jsonb_build_object('full_name',v_name,'phone',v_phone)
    );

    return jsonb_build_object(
      'ok', true,
      'action', v_audit_action,
      'role_id', v_existing_id,
      'user_id', v_target,
      'role', v_role,
      'is_active', true
    );
  end if;

  begin v_role_id := (p_payload->>'role_id')::uuid;
  exception when others then raise exception 'ROLE_ID_REQUIRED: role_id must be a UUID'; end;
  v_active := coalesce((p_payload->>'is_active')::boolean, false);

  select ur.role, ur.is_active
    into v_old_role, v_old_active
  from public.user_roles ur
  where ur.id = v_role_id and ur.user_id = v_target
    and ur.branch_id = v_branch
  for update;
  if not found then
    raise exception 'ROLE_ASSIGNMENT_NOT_FOUND: team role assignment was not found';
  end if;

  if v_old_role = 'owner' and v_old_active and not v_active then
    select count(*) into v_active_owner_count
    from public.user_roles ur
    left join public.branches b on b.id = ur.branch_id
    where ur.role = 'owner' and ur.is_active
      and (ur.branch_id is null or b.restaurant_id = v_restaurant_id);
    if v_active_owner_count <= 1 then
      raise exception 'LAST_OWNER_PROTECTED: cannot deactivate the last active owner';
    end if;
  end if;

  if v_old_role = 'rider' and v_old_active and not v_active then
    if exists (
      select 1
      from public.delivery_assignments da
      join public.delivery_tasks dt on dt.id = da.delivery_task_id
      where da.rider_user_id = v_target
        and da.is_current
        and dt.status in ('assigned','accepted','arrived_at_restaurant','out_for_delivery','picked_up','failed')
    ) then
      raise exception 'RIDER_HAS_ACTIVE_DELIVERIES: reassign or finish this rider active delivery before deactivation';
    end if;
  end if;

  update public.user_roles set is_active = v_active where id = v_role_id;

  if v_old_role = 'rider' and v_active then
    select up.full_name, up.phone into v_name, v_phone
    from public.user_profiles up where up.id = v_target;
    insert into public.rider_profiles(
      user_id, branch_id, rider_code, display_name, phone,
      availability_status, is_active, updated_at
    )
    values (
      v_target, v_branch,
      'PB-R-' || upper(substr(replace(v_target::text,'-',''),1,8)),
      coalesce(v_name, 'Flame Chick Rider'), v_phone,
      'offline', true, v_now
    )
    on conflict (user_id) do update
      set branch_id = excluded.branch_id,
          display_name = coalesce(excluded.display_name, public.rider_profiles.display_name),
          phone = coalesce(excluded.phone, public.rider_profiles.phone),
          availability_status = 'offline',
          is_active = true,
          updated_at = v_now;
  elsif v_old_role = 'rider' then
    update public.rider_profiles
    set is_active = false, availability_status = 'offline', updated_at = v_now
    where user_id = v_target and branch_id = v_branch;
  end if;

  insert into public.staff_role_audit(
    restaurant_id, branch_id, actor_user_id, target_user_id, action,
    old_role, new_role, old_is_active, new_is_active, details
  )
  values (
    v_restaurant_id, v_branch, v_actor, v_target,
    case when v_active then 'role_reactivated' else 'role_deactivated' end,
    v_old_role, v_old_role, v_old_active, v_active,
    jsonb_build_object('role_id',v_role_id)
  );

  return jsonb_build_object(
    'ok', true,
    'action', case when v_active then 'role_reactivated' else 'role_deactivated' end,
    'role_id', v_role_id,
    'user_id', v_target,
    'role', v_old_role,
    'is_active', v_active
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.hfp_rider_get_jobs()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_branch_id uuid;
  v_profile_active boolean;
  v_availability text;
  v_tasks jsonb;
  v_offers jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501',
      MESSAGE='RIDER_AUTH_REQUIRED: Sign in to load your deliveries.';
  END IF;

  SELECT ur.branch_id
    INTO v_branch_id
  FROM public.user_roles ur
  WHERE ur.user_id=v_user_id
    AND ur.role='rider'
    AND ur.is_active=true
    AND ur.branch_id IS NOT NULL
  ORDER BY ur.branch_id
  LIMIT 1;

  IF v_branch_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501',
      MESSAGE='RIDER_ROLE_REQUIRED: An active HFP rider role is required.';
  END IF;

  SELECT rp.is_active, rp.availability_status
    INTO v_profile_active, v_availability
  FROM public.rider_profiles rp
  WHERE rp.user_id=v_user_id
    AND rp.branch_id=v_branch_id
  LIMIT 1;

  IF NOT FOUND OR v_profile_active IS NOT TRUE OR v_availability='suspended' THEN
    RAISE EXCEPTION USING ERRCODE='42501',
      MESSAGE='RIDER_PROFILE_REQUIRED: Your active HFP rider profile was not found.';
  END IF;

  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',dt.id,
        'status',dt.status,
        'recipient_name_snapshot',dt.recipient_name_snapshot,
        'recipient_phone_snapshot',dt.recipient_phone_snapshot,
        'address_snapshot',dt.address_snapshot,
        'area_name_snapshot',dt.area_name_snapshot,
        'delivery_fee_snapshot',dt.delivery_fee_snapshot,
        'delivery_instructions_snapshot',dt.delivery_instructions_snapshot,
        'dispatch_started_at',dt.dispatch_started_at,
        'assigned_at',dt.assigned_at,
        'picked_up_at',dt.picked_up_at,
        'out_for_delivery_at',dt.out_for_delivery_at,
        'delivered_at',dt.delivered_at,
        'failed_at',dt.failed_at,
        'failure_reason',dt.failure_reason,
        'return_reported_at',dt.return_reported_at,
        'return_confirmed_at',dt.return_confirmed_at,
        'orders',jsonb_build_object(
          'id',o.id,
          'order_number',o.order_number,
          'status',o.status,
          'fulfillment_type',o.fulfillment_type,
          'total',o.total,
          'payment_status',o.payment_status,
          'customer_name',o.customer_name,
          'customer_phone',o.customer_phone,
          'delivery_address',o.delivery_address,
          'delivery_instructions',o.delivery_instructions,
          'order_items',(
            SELECT coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'id',oi.id,
                  'line_number',oi.line_number,
                  'quantity',oi.quantity,
                  'product_name_snapshot',oi.product_name_snapshot,
                  'variant_label_snapshot',oi.variant_label_snapshot,
                  'deal_title_snapshot',oi.deal_title_snapshot,
                  'line_total',oi.line_total,
                  'item_notes',oi.item_notes,
                  'order_item_modifiers',(
                    SELECT coalesce(
                      jsonb_agg(jsonb_build_object(
                        'id',oim.id,
                        'modifier_group_name_snapshot',oim.modifier_group_name_snapshot,
                        'modifier_name_snapshot',oim.modifier_name_snapshot,
                        'quantity',oim.quantity,
                        'total_price_snapshot',oim.total_price_snapshot
                      ) ORDER BY oim.id),
                      '[]'::jsonb
                    )
                    FROM public.order_item_modifiers oim
                    WHERE oim.order_item_id=oi.id
                  )
                ) ORDER BY oi.line_number,oi.id
              ),
              '[]'::jsonb
            )
            FROM public.order_items oi
            WHERE oi.order_id=o.id
          )
        ),
        'delivery_assignments',(
          SELECT coalesce(
            jsonb_agg(jsonb_build_object(
              'id',da.id,
              'rider_user_id',da.rider_user_id,
              'status',da.status,
              'is_current',da.is_current,
              'assigned_at',da.assigned_at,
              'accepted_at',da.accepted_at,
              'arrived_at',da.arrived_at,
              'picked_up_at',da.picked_up_at,
              'delivered_at',da.delivered_at,
              'created_at',da.created_at
            ) ORDER BY da.assigned_at DESC,da.created_at DESC),
            '[]'::jsonb
          )
          FROM public.delivery_assignments da
          WHERE da.delivery_task_id=dt.id
            AND da.rider_user_id=v_user_id
            AND da.is_current=true
            AND da.status IN ('assigned','accepted','arrived_at_restaurant','out_for_delivery','picked_up','failed')
        )
      )
      ORDER BY dt.created_at ASC
    ),
    '[]'::jsonb
  )
  INTO v_tasks
  FROM public.delivery_tasks dt
  JOIN public.orders o ON o.id=dt.order_id
  WHERE dt.branch_id=v_branch_id
    AND dt.status IN ('assigned','accepted','arrived_at_restaurant','out_for_delivery','picked_up','failed')
    AND dt.return_confirmed_at IS NULL
    AND o.fulfillment_type='delivery'
    AND EXISTS (
      SELECT 1
      FROM public.delivery_assignments da
      WHERE da.delivery_task_id=dt.id
        AND da.rider_user_id=v_user_id
        AND da.is_current=true
        AND da.status IN ('assigned','accepted','arrived_at_restaurant','out_for_delivery','picked_up','failed')
    );

  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',dto.id,
        'delivery_task_id',dto.delivery_task_id,
        'offer_round',dto.offer_round,
        'offered_at',dto.offered_at,
        'expires_at',dto.expires_at,
        'delivery_tasks',jsonb_build_object(
          'id',dt.id,
          'status',dt.status,
          'area_name_snapshot',dt.area_name_snapshot,
          'delivery_fee_snapshot',dt.delivery_fee_snapshot,
          'orders',jsonb_build_object(
            'order_number',o.order_number,
            'status',o.status
          )
        )
      )
      ORDER BY dto.offered_at ASC
    ),
    '[]'::jsonb
  )
  INTO v_offers
  FROM public.delivery_task_offers dto
  JOIN public.delivery_tasks dt ON dt.id=dto.delivery_task_id
  JOIN public.orders o ON o.id=dt.order_id
  WHERE dto.rider_user_id=v_user_id
    AND dto.status='offered'
    AND dto.expires_at > pg_catalog.now()
    AND dt.status='offering'
    AND o.status='ready';

  RETURN jsonb_build_object(
    'ok',true,
    'view','rider',
    'data',v_tasks,
    'offers',v_offers
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.hfp_rider_presence(p_online boolean DEFAULT true, p_update_preference boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_branch_id uuid;
  v_profile public.rider_profiles%rowtype;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_accepting_jobs boolean;
  v_busy boolean := false;
  v_availability text;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='RIDER_AUTH_REQUIRED: Sign in to update rider availability.'; END IF;
  SELECT ur.branch_id INTO v_branch_id FROM public.user_roles ur
  WHERE ur.user_id=v_user_id AND ur.role='rider' AND ur.is_active=true AND ur.branch_id IS NOT NULL
  ORDER BY ur.branch_id LIMIT 1;
  IF v_branch_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='RIDER_ROLE_REQUIRED: An active Flame Chick rider role is required.'; END IF;
  SELECT rp.* INTO v_profile FROM public.rider_profiles rp
  WHERE rp.user_id=v_user_id AND rp.branch_id=v_branch_id AND rp.is_active=true FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='RIDER_PROFILE_REQUIRED: Your active rider profile was not found.'; END IF;
  IF v_profile.availability_status='suspended' THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='RIDER_SUSPENDED: Your rider account is suspended.'; END IF;

  IF coalesce(p_update_preference,false) AND NOT coalesce(p_online,false)
     AND EXISTS (SELECT 1 FROM public.delivery_assignments da
       WHERE da.rider_user_id=v_user_id AND da.is_current=true
         AND da.status IN ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery','failed')) THEN
    RAISE EXCEPTION USING ERRCODE='22023',
      MESSAGE='RIDER_ASSIGNMENT_ACTIVE: You have a pending or active delivery. Accept or decline the assignment before going offline.';
  END IF;

  v_accepting_jobs := CASE WHEN p_update_preference THEN coalesce(p_online,false) ELSE coalesce(v_profile.accepting_jobs,false) END;
  IF coalesce(p_online,false) AND NOT coalesce(p_update_preference,false)
     AND v_profile.last_seen_at IS NOT NULL AND v_profile.last_seen_at > v_now - interval '90 seconds' THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'online',true,'accepting_jobs',v_profile.accepting_jobs,
      'availability_status',v_profile.availability_status,'last_seen_at',v_profile.last_seen_at,'throttled',true);
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.delivery_tasks dt
    JOIN public.delivery_assignments da ON da.delivery_task_id=dt.id
    WHERE dt.branch_id=v_branch_id AND da.rider_user_id=v_user_id AND da.is_current=true
      AND da.status IN ('assigned','accepted','arrived_at_restaurant','picked_up','out_for_delivery','failed')
      AND dt.status IN ('assigned','accepted','arrived_at_restaurant','out_for_delivery','failed')
      AND dt.return_confirmed_at IS NULL) INTO v_busy;

  v_availability := CASE WHEN v_busy THEN 'busy'
    WHEN coalesce(p_online,false) AND v_accepting_jobs THEN 'available' ELSE 'offline' END;
  UPDATE public.rider_profiles SET availability_status=v_availability,accepting_jobs=v_accepting_jobs,
    last_seen_at=v_now,updated_at=v_now
  WHERE user_id=v_user_id AND branch_id=v_branch_id AND is_active=true AND availability_status<>'suspended';
  RETURN pg_catalog.jsonb_build_object('ok',true,'online',coalesce(p_online,false),
    'accepting_jobs',v_accepting_jobs,'availability_status',v_availability,'last_seen_at',v_now,'throttled',false);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.hfp_update_order_status(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order_id uuid;
  v_actor_user_id uuid;
  v_actor_role text;
  v_actor_type text;
  v_to_status text;
  v_reason text;
  v_order public.orders%rowtype;
  v_allowed boolean := false;
begin
  v_order_id := nullif(p_payload->>'order_id','')::uuid;
  v_actor_user_id := nullif(p_payload->>'actor_user_id','')::uuid;
  v_to_status := lower(coalesce(p_payload->>'to_status',''));
  v_reason := nullif(btrim(p_payload->>'reason'), '');

  if v_order_id is null or v_actor_user_id is null or v_to_status = '' then
    raise exception using errcode = '22023', message = 'STATUS_REQUEST_INVALID: order_id, to_status, and authenticated actor are required.';
  end if;
  if v_to_status not in ('accepted','preparing','ready','collected','served','completed','rejected','cancelled') then
    raise exception using errcode = '22023', message = 'STATUS_NOT_ALLOWED: This endpoint cannot set the requested order status.';
  end if;

  select * into v_order from public.orders where id = v_order_id for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'ORDER_NOT_FOUND: Order was not found.';
  end if;

  select ur.role into v_actor_role
  from public.user_roles ur
  where ur.user_id = v_actor_user_id
    and ur.is_active = true
    and (ur.branch_id is null or ur.branch_id = v_order.branch_id)
    and ur.role in ('owner','admin','manager','cashier','kitchen')
  order by case ur.role when 'owner' then 1 when 'admin' then 2 when 'manager' then 3 when 'cashier' then 4 else 5 end
  limit 1;

  if v_actor_role is null then
    raise exception using errcode = '42501', message = 'STAFF_ROLE_REQUIRED: This account cannot update HFP order statuses.';
  end if;

  if v_order.status = v_to_status then
    return jsonb_build_object('ok', true, 'unchanged', true, 'order_id', v_order.id, 'order_number', v_order.order_number, 'status', v_order.status);
  end if;

  if v_to_status = 'accepted' then
    v_allowed := v_order.status = 'new' and v_actor_role in ('owner','admin','manager','cashier');
  elsif v_to_status = 'preparing' then
    v_allowed := v_order.status in ('new','accepted') and v_actor_role in ('owner','admin','manager','cashier','kitchen');
  elsif v_to_status = 'ready' then
    v_allowed := v_order.status = 'preparing' and v_actor_role in ('owner','admin','manager','cashier','kitchen');
  elsif v_to_status = 'collected' then
    v_allowed := v_order.status = 'ready' and v_order.fulfillment_type = 'pickup' and v_actor_role in ('owner','admin','manager','cashier');
  elsif v_to_status = 'served' then
    v_allowed := v_order.status = 'ready' and v_order.fulfillment_type = 'dine_in' and v_actor_role in ('owner','admin','manager','cashier','kitchen');
  elsif v_to_status = 'completed' then
    v_allowed := v_order.status in ('collected','served','delivered') and v_actor_role in ('owner','admin','manager','cashier');
  elsif v_to_status = 'rejected' then
    v_allowed := v_order.status in ('new','accepted') and v_actor_role in ('owner','admin','manager','cashier') and v_reason is not null;
  elsif v_to_status = 'cancelled' then
    v_allowed := v_order.status in ('new','accepted','preparing','ready') and v_actor_role in ('owner','admin','manager','cashier') and v_reason is not null;
  end if;

  if not v_allowed then
    raise exception using errcode = '22023', message = 'STATUS_TRANSITION_NOT_ALLOWED: The requested status transition is not permitted for this order, fulfilment type, or staff role.';
  end if;

  v_actor_type := case when v_actor_role in ('owner','admin') then 'admin' else 'staff' end;

  update public.orders
  set status = v_to_status,
      accepted_at = case when v_to_status = 'accepted' then coalesce(accepted_at, pg_catalog.now()) else accepted_at end,
      accepted_by = case when v_to_status = 'accepted' then v_actor_user_id else accepted_by end,
      preparing_at = case when v_to_status = 'preparing' then coalesce(preparing_at, pg_catalog.now()) else preparing_at end,
      ready_at = case when v_to_status = 'ready' then coalesce(ready_at, pg_catalog.now()) else ready_at end,
      collected_at = case when v_to_status = 'collected' then coalesce(collected_at, pg_catalog.now()) else collected_at end,
      served_at = case when v_to_status = 'served' then coalesce(served_at, pg_catalog.now()) else served_at end,
      completed_at = case when v_to_status = 'completed' then coalesce(completed_at, pg_catalog.now()) else completed_at end,
      rejected_at = case when v_to_status = 'rejected' then coalesce(rejected_at, pg_catalog.now()) else rejected_at end,
      rejected_by = case when v_to_status = 'rejected' then v_actor_user_id else rejected_by end,
      rejection_reason = case when v_to_status = 'rejected' then v_reason else rejection_reason end,
      cancelled_at = case when v_to_status = 'cancelled' then coalesce(cancelled_at, pg_catalog.now()) else cancelled_at end,
      cancelled_by_type = case when v_to_status = 'cancelled' then 'staff' else cancelled_by_type end,
      cancelled_by_user_id = case when v_to_status = 'cancelled' then v_actor_user_id else cancelled_by_user_id end,
      cancellation_reason = case when v_to_status = 'cancelled' then v_reason else cancellation_reason end,
      last_status_changed_by = v_actor_user_id,
      last_status_actor_type = v_actor_type,
      last_status_change_reason = v_reason
  where id = v_order_id
  returning * into v_order;

  if v_to_status = 'cancelled' then
    update public.delivery_tasks
    set status = 'cancelled', failure_reason = coalesce(v_reason, 'Order cancelled by staff')
    where order_id = v_order_id
      and status not in ('delivered','failed','cancelled');
  end if;

  return jsonb_build_object(
    'ok', true,
    'unchanged', false,
    'order_id', v_order.id,
    'order_number', v_order.order_number,
    'status', v_order.status,
    'updated_at', v_order.updated_at
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.hfp_verify_delivery_push_webhook(p_token text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(p_token <> '' and exists (
    select 1 from private.rider_push_config c
    where c.singleton = true and c.webhook_token = p_token
  ), false);
$function$
;

