create policy "order_items_current_rider_read" on "public"."order_items" as permissive for SELECT to authenticated using ((EXISTS ( SELECT 1
   FROM ((((orders o
     JOIN delivery_tasks dt ON ((dt.order_id = o.id)))
     JOIN delivery_assignments da ON ((da.delivery_task_id = dt.id)))
     JOIN user_roles ur ON (((ur.user_id = da.rider_user_id) AND (ur.role = 'rider'::text) AND (ur.is_active = true) AND ((ur.branch_id IS NULL) OR (ur.branch_id = dt.branch_id)))))
     JOIN rider_profiles rp ON (((rp.user_id = da.rider_user_id) AND (rp.branch_id = dt.branch_id) AND (rp.is_active = true) AND (rp.availability_status <> 'suspended'::text))))
  WHERE ((o.id = order_items.order_id) AND (da.rider_user_id = ( SELECT auth.uid() AS uid)) AND (da.is_current = true) AND (da.status = ANY (ARRAY['assigned'::text, 'accepted'::text, 'arrived_at_restaurant'::text, 'picked_up'::text, 'out_for_delivery'::text, 'failed'::text]))))));

