     JOIN rider_profiles rp ON (((rp.user_id = da.rider_user_id) AND (rp.branch_id = dt.branch_id) AND (rp.is_active = true) AND (rp.availability_status <> 'suspended'::text))))
  WHERE ((dt.order_id = orders.id) AND (da.rider_user_id = ( SELECT auth.uid() AS uid)) AND (da.is_current = true) AND (da.status = ANY (ARRAY['assigned'::text, 'accepted'::text, 'arrived_at_restaurant'::text, 'picked_up'::text, 'out_for_delivery'::text, 'failed'::text]))))));

