create or replace view public."v_pos_orders" with (security_invoker=true) as  SELECT id,
    branch_id,
    order_number,
    local_order_id,
    idempotency_key,
    request_hash,
    source,
    source_reference,
    fulfillment_type,
    status,
    customer_id,
    customer_name,
    customer_phone,
    customer_email,
    delivery_address,
    delivery_area_id,
    delivery_area_name_snapshot,
    delivery_area_fee_snapshot,
    delivery_latitude,
    delivery_longitude,
    delivery_instructions,
    table_id,
    table_number_snapshot,
    subtotal,
    discount_amount,
    tax_amount,
    service_charge,
    delivery_fee,
    tip_amount,
    total,
    paid_amount,
    balance_due,
    currency_code,
    payment_status,
    payment_method_summary,
    notes,
    internal_notes,
    promo_snapshot,
    address_snapshot,
    source_payload_snapshot,
    tracking_token_hash,
    cashier_id,
    pos_device_id,
    register_session_id,
    accepted_by,
    rejected_by,
    rejection_reason,
    cancelled_at,
    cancelled_by_type,
    cancelled_by_user_id,
    cancellation_reason,
    placed_at,
    accepted_at,
    preparing_at,
    ready_at,
    out_for_delivery_at,
    delivered_at,
    collected_at,
    served_at,
    completed_at,
    rejected_at,
    created_at,
    updated_at
   FROM orders
  WHERE status = ANY (ARRAY['new'::text, 'accepted'::text]);;

